import React, { useEffect, useState } from "react";
import { Eye, Shield, RefreshCw, ChevronLeft, ChevronRight, Filter, Search, ArrowRight } from "lucide-react";
import { fetchWithAuth } from "@/lib/fetchWithAuth";

interface AuditLog {
  id: string;
  admin_id: string;
  admin_email: string;
  action: string;
  target_id: string | null;
  ip_address: string | null;
  user_agent: string | null;
  details: any;
  timestamp: string;
}

interface AuditLogsPanelProps {
  api: string;
  getAuthHeaders: () => Record<string, string>;
  triggerToast: (msg: string, type: "success" | "error" | "info") => void;
}

export function AuditLogsPanel({ api, getAuthHeaders, triggerToast }: AuditLogsPanelProps) {
  const [logs, setLogs] = useState<AuditLog[]>([]);
  const [loading, setLoading] = useState(true);
  const [isFallback, setIsFallback] = useState(false);
  
  // Pagination & Filtering state
  const [total, setTotal] = useState(0);
  const [limit, setLimit] = useState(50); // Default 50
  const [offset, setOffset] = useState(0);
  const [actionFilter, setActionFilter] = useState("");
  const [expandedLogId, setExpandedLogId] = useState<string | null>(null);

  const fetchLogs = async () => {
    setLoading(true);
    // Enforce limits: default = 50, max = 100
    const safeLimit = Math.min(100, Math.max(1, limit));
    try {
      let url = `${api}/api/admin/audit-logs?limit=${safeLimit}&offset=${offset}`;
      if (actionFilter) {
        url += `&action=${actionFilter}`;
      }

      const res = await fetchWithAuth(url, { headers: getAuthHeaders() });
      const json = await res.json();
      if (json.success) {
        setLogs(json.data || []);
        setTotal(json.pagination?.total || 0);
        setIsFallback(!!json.fallback);
      } else {
        triggerToast(json.error || "Failed to load audit logs", "error");
      }
    } catch {
      triggerToast("Network error loading security audit logs", "error");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchLogs();
  }, [offset, limit, actionFilter]);

  const handlePageChange = (direction: "prev" | "next") => {
    if (direction === "prev" && offset > 0) {
      setOffset(Math.max(0, offset - limit));
    } else if (direction === "next" && offset + limit < total) {
      setOffset(offset + limit);
    }
  };

  // Renders beautiful colorized JSON Diff
  const renderJSONDetails = (details: any) => {
    if (!details || typeof details !== "object") return <span className="text-muted font-mono text-xs">No extra metadata</span>;
 
    // Check if it's a state change with "previous" and current properties
    const keys = Object.keys(details).filter(k => k !== "previous");
    const hasPrevious = !!details.previous;
 
    return (
      <div className="space-y-2 bg-input/70 border border-subtle rounded-lg p-3 text-xs font-mono select-text">
        {hasPrevious ? (
          <div className="space-y-1">
            <div className="text-secondary font-semibold mb-1 border-b border-subtle pb-1">✏️ Attribute Changes:</div>
            {keys.map((k) => {
              const prevVal = details.previous[k];
              const newVal = details[k];
              if (JSON.stringify(prevVal) === JSON.stringify(newVal)) return null;
 
              return (
                <div key={k} className="grid grid-cols-1 sm:grid-cols-3 gap-1 py-1 hover:bg-card px-1 rounded transition">
                  <span className="text-secondary font-semibold truncate">{k}:</span>
                  <span className="text-red-650 dark:text-red-400/90 line-through bg-red-950/10 dark:bg-red-950/20 px-1 rounded w-fit truncate">
                    {prevVal !== undefined ? String(prevVal) : "undefined"}
                  </span>
                  <span className="text-emerald-700 dark:text-emerald-400 bg-emerald-950/10 dark:bg-emerald-950/20 px-1 rounded w-fit flex items-center gap-1 font-bold truncate">
                    <ArrowRight size={10} /> {newVal !== undefined ? String(newVal) : "undefined"}
                  </span>
                </div>
              );
            })}
          </div>
        ) : (
          <pre className="text-[11px] text-secondary overflow-x-auto whitespace-pre-wrap leading-relaxed">
            {JSON.stringify(details, null, 2)}
          </pre>
        )}
      </div>
    );
  };

  const actions = [
    { value: "", label: "All Actions" },
    { value: "VIEW_PROVIDER_SECRET", label: "VIEW_PROVIDER_SECRET" },
    { value: "CACHE_CLEAR", label: "CACHE_CLEAR" },
    { value: "BLOCK", label: "BLOCK" },
    { value: "UNBLOCK", label: "UNBLOCK" },
    { value: "RESET_LIMITS", label: "RESET_LIMITS" },
    { value: "CHANGE_PLAN", label: "CHANGE_PLAN" },
    { value: "OVERRIDE_QUOTA", label: "OVERRIDE_QUOTA" },
    { value: "BULK_BLOCK", label: "BULK_BLOCK" },
    { value: "BULK_UNBLOCK", label: "BULK_UNBLOCK" },
    { value: "TERMINATE_SESSIONS", label: "TERMINATE_SESSIONS" },
    { value: "ADJUST_CREDITS", label: "ADJUST_CREDITS" },
    { value: "PROVIDER_DEGRADATION", label: "PROVIDER_DEGRADATION" }
  ];

  const currentPage = Math.floor(offset / limit) + 1;
  const totalPages = Math.ceil(total / limit) || 1;

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center border-b border-subtle pb-4">
        <div>
          <h2 className="text-xl font-bold text-main flex items-center gap-2">
            <Shield className="text-indigo-400" /> Immutable Security Audit Logs
          </h2>
          <p className="text-xs text-secondary">Security audit trail tracking admin mutations, session kills, and API secret reveals.</p>
        </div>
        <button onClick={fetchLogs} disabled={loading} className="p-2 rounded-lg bg-input hover:bg-card text-secondary hover:text-main border border-subtle transition">
          <RefreshCw size={16} />
        </button>
      </div>

      {isFallback && (
        <div className="flex items-center gap-3 p-4 bg-amber-500/10 dark:bg-amber-500/20 border border-amber-500/20 dark:border-amber-500/30 text-amber-700 dark:text-amber-400 text-xs font-mono backdrop-blur-md shadow-lg animate-in fade-in duration-300">
          <Shield className="w-5 h-5 text-amber-500 shrink-0 animate-pulse" />
          <div>
            <span className="font-bold uppercase tracking-wider block">WARNING — CACHE MODE ACTIVE</span>
            <span className="text-[10px] text-muted mt-1 block leading-normal normal-case">
              Fallback cache mode active while persistent provider storage is temporarily unavailable.
            </span>
          </div>
        </div>
      )}

      {/* Filters */}
      <div className="flex flex-col sm:flex-row gap-3">
        <div className="flex-1 relative">
          <Filter className="absolute left-3 top-1/2 -translate-y-1/2 text-muted" size={14} />
          <select value={actionFilter} onChange={(e) => { setActionFilter(e.target.value); setOffset(0); }}
            className="w-full pl-9 pr-4 py-2 bg-input border border-subtle rounded-lg text-sm text-secondary focus:outline-none focus:border-strong focus:ring-1 focus:ring-strong">
            {actions.map(a => <option key={a.value} value={a.value} className="bg-card text-main">{a.label}</option>)}
          </select>
        </div>
 
        <div className="flex items-center gap-2">
          <label className="text-xs text-secondary whitespace-nowrap">Page Size:</label>
          <select value={limit} onChange={(e) => { setLimit(parseInt(e.target.value, 10)); setOffset(0); }}
            className="bg-input border border-subtle rounded-lg px-2 py-2 text-sm text-secondary focus:outline-none">
            <option value="50" className="bg-card text-main">50 (Default)</option>
            <option value="100" className="bg-card text-main">100 (Max)</option>
          </select>
        </div>
      </div>

      <div className="bg-card border border-subtle rounded-xl overflow-hidden shadow-md">
        {loading ? (
          <div className="flex items-center justify-center py-16 gap-3 text-muted">
            <RefreshCw className="animate-spin text-muted" size={24} /> Loading audit trail...
          </div>
        ) : logs.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-16 text-muted gap-2">
            <Shield size={36} className="text-muted" />
            <p className="text-sm">No audit logs found matching selected action.</p>
          </div>
        ) : (
          <div className="divide-y divide-subtle">
            {logs.map((log) => {
              const isExpanded = expandedLogId === log.id;
              const isSecretReveal = log.action === "VIEW_PROVIDER_SECRET";
 
              return (
                <div key={log.id} className={`p-4 transition ${isSecretReveal ? "bg-red-500/5 dark:bg-red-950/5 hover:bg-red-500/10 dark:hover:bg-red-950/10" : "hover:bg-input/20"}`}>
                  <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-3">
                    <div className="space-y-1">
                      <div className="flex flex-wrap items-center gap-2">
                        <span className={`text-[10px] font-extrabold px-2 py-0.5 rounded font-mono ${
                          isSecretReveal 
                            ? "bg-red-500/10 text-red-650 dark:text-red-400 border border-red-500/20 dark:border-red-800/30" 
                            : log.action === "CACHE_CLEAR" 
                            ? "bg-amber-500/10 text-amber-700 dark:text-amber-400 border border-amber-500/20 dark:border-amber-800/30"
                            : "bg-input border border-subtle text-secondary"
                        }`}>
                          {log.action}
                        </span>
                        <span className="text-xs text-secondary font-semibold">{log.admin_email}</span>
                      </div>
                      <div className="text-xs text-muted">
                        IP: <span className="font-mono text-secondary">{log.ip_address || "internal"}</span> · Target ID: <span className="font-mono text-secondary">{log.target_id || "N/A"}</span>
                      </div>
                    </div>
 
                    <div className="flex items-center gap-4 text-xs">
                      <span className="text-muted">{new Date(log.timestamp).toLocaleString("en-IN")}</span>
                      <button onClick={() => setExpandedLogId(isExpanded ? null : log.id)} className="flex items-center gap-1 py-1 px-2.5 rounded bg-input hover:bg-card border border-subtle text-[11px] font-bold text-secondary hover:text-main transition">
                        <Eye size={12} /> {isExpanded ? "Collapse" : "Inspect"}
                      </button>
                    </div>
                  </div>
 
                  {isExpanded && (
                    <div className="mt-4 pt-3 border-t border-subtle animate-fade-in space-y-3">
                      <div className="text-xs text-secondary">
                        <span className="font-semibold text-muted">User Agent:</span> {log.user_agent || "N/A"}
                      </div>
                      <div>
                        <span className="text-xs font-semibold text-muted block mb-1">Payload / State Delta:</span>
                        {renderJSONDetails(log.details)}
                      </div>
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        )}
 
        {/* Pagination Controls */}
        <div className="px-5 py-3.5 border-t border-subtle bg-input/40 flex justify-between items-center text-xs text-secondary">
          <div>
            Showing <span className="font-semibold text-main">{offset + 1}</span> - <span className="font-semibold text-main">{Math.min(offset + limit, total)}</span> of <span className="font-semibold text-main">{total}</span> audits
          </div>
 
          <div className="flex items-center gap-3">
            <button onClick={() => handlePageChange("prev")} disabled={offset === 0}
              className="p-1.5 rounded-lg bg-input hover:bg-card border border-subtle text-secondary hover:text-main disabled:opacity-40 disabled:cursor-not-allowed transition">
              <ChevronLeft size={14} />
            </button>
            <span className="font-medium text-main">
              Page {currentPage} of {totalPages}
            </span>
            <button onClick={() => handlePageChange("next")} disabled={offset + limit >= total}
              className="p-1.5 rounded-lg bg-input hover:bg-card border border-subtle text-secondary hover:text-main disabled:opacity-40 disabled:cursor-not-allowed transition">
              <ChevronRight size={14} />
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}
