"use client";

import React, { useEffect, useState, useCallback } from "react";
import { 
  Megaphone, Sparkles, Tag, CheckCircle2, Save, 
  Eye, RefreshCw, Gift, Zap, Bell, Check, ShieldCheck, Flame
} from "lucide-react";
import { fetchWithAuth } from "@/lib/fetchWithAuth";

interface OffersPopupPanelProps {
  api: string;
  getAuthHeaders: () => Record<string, string>;
  triggerToast: (msg: string, type: "success" | "error" | "info") => void;
}

export function OffersPopupPanel({ api, getAuthHeaders, triggerToast }: OffersPopupPanelProps) {
  const [loading, setLoading] = useState<boolean>(true);
  const [saving, setSaving] = useState<boolean>(false);
  const [testEmail, setTestEmail] = useState<string>("peershaikh25@gmail.com");
  const [testSending, setTestSending] = useState<boolean>(false);
  const [broadcasting, setBroadcasting] = useState<boolean>(false);
  const [broadcastResult, setBroadcastResult] = useState<any>(null);
  
  const [config, setConfig] = useState({
    isActive: true,
    title: "Festive Travel Freedom Offer",
    subtitle: "Get 30 Days of Safar Pro Monthly for just ₹19! Unlimited AI split routes, zero-waitlist discoveries & live tracking.",
    badgeText: "SPECIAL PROMO",
    offerPrice: "₹19",
    originalPrice: "₹49",
    couponCode: "OFFER19",
    planType: "safar_pro_30d",
    durationDays: 30,
    ctaText: "Claim 1 Month Pro for ₹19",
    features: [
      "Unlimited AI Hidden Split Journeys",
      "Live Train GPS & Delay Alerts",
      "Instant PNR Confirmation Probabilities",
      "High Priority Support & Auto-Refresh"
    ]
  });

  const [featuresText, setFeaturesText] = useState<string>(
    config.features.join("\n")
  );

  const fetchConfig = useCallback(async () => {
    try {
      setLoading(true);
      const res = await fetchWithAuth(`${api}/api/content/admin/popup-offer`, {
        headers: getAuthHeaders()
      });
      if (res.ok) {
        const json = await res.json();
        if (json.success && json.data) {
          setConfig(json.data);
          if (Array.isArray(json.data.features)) {
            setFeaturesText(json.data.features.join("\n"));
          }
        }
      }
    } catch (err: any) {
      console.error("[POPUP_OFFER_FETCH_ERROR]", err);
    } finally {
      setLoading(false);
    }
  }, [api, getAuthHeaders]);

  useEffect(() => {
    fetchConfig();
    try {
      const saved = localStorage.getItem("trayago_diwali_broadcast_result");
      if (saved) {
        setBroadcastResult(JSON.parse(saved));
      }
    } catch (_) {}
  }, [fetchConfig]);

  const handleSave = async () => {
    try {
      setSaving(true);
      const splitFeatures = featuresText
        .split("\n")
        .map((f) => f.trim())
        .filter(Boolean);

      const payload = {
        ...config,
        features: splitFeatures,
        couponCode: (config.couponCode || "").trim().toUpperCase()
      };

      const res = await fetchWithAuth(`${api}/api/content/admin/popup-offer`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          ...getAuthHeaders()
        },
        body: JSON.stringify(payload)
      });

      const json = await res.json();
      if (json.success) {
        setConfig(json.data);
        triggerToast("Promotional offer broadcast & coupon code synced successfully!", "success");
      } else {
        triggerToast(json.error || "Failed to save configuration", "error");
      }
    } catch (err: any) {
      triggerToast("Network error while saving offer config", "error");
    } finally {
      setSaving(false);
    }
  };

  const handleSendTestEmail = async () => {
    try {
      setTestSending(true);
      const res = await fetchWithAuth(`${api}/api/admin/broadcast/diwali-promo`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          ...getAuthHeaders()
        },
        body: JSON.stringify({ mode: "test", testEmail })
      });
      const json = await res.json();
      if (json.success && json.delivered) {
        triggerToast(`Test email delivered to ${testEmail}! Check your inbox.`, "success");
      } else {
        triggerToast(json.message || "Failed to deliver test email.", "error");
      }
    } catch (err: any) {
      triggerToast(`Network error: ${err.message}`, "error");
    } finally {
      setTestSending(false);
    }
  };

  const handleBroadcastAll = async (resumeOffset: number = 0) => {
    const offsetNum = typeof resumeOffset === 'number' ? resumeOffset : 0;
    const isResuming = offsetNum > 0;
    const confirmPrompt = window.confirm(
      isResuming
        ? `Resume broadcast to the remaining ${542 - offsetNum} users who did not receive the email yet?`
        : "Are you sure you want to broadcast the Diwali Special Offer (₹35) to ALL 500+ registered users now?"
    );
    if (!confirmPrompt) return;

    try {
      setBroadcasting(true);
      if (!isResuming) setBroadcastResult(null);
      const res = await fetchWithAuth(`${api}/api/admin/broadcast/diwali-promo`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          ...getAuthHeaders()
        },
        body: JSON.stringify({ mode: "broadcast", offset: offsetNum })
      });
      const json = await res.json();
      if (json.success) {
        setBroadcastResult(json);
        try {
          localStorage.setItem("trayago_diwali_broadcast_result", JSON.stringify(json));
        } catch (_) {}
        triggerToast(`Diwali campaign broadcast finished! Sent: ${json.sentCount}/${json.totalRecipients}`, "success");
      } else {
        triggerToast(json.error || "Broadcast failed", "error");
      }
    } catch (err: any) {
      triggerToast(`Broadcast error: ${err.message}`, "error");
    } finally {
      setBroadcasting(false);
    }
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 border-b border-subtle pb-4">
        <div>
          <h2 className="text-xl font-bold flex items-center gap-2 text-main">
            <Megaphone className="text-primary" size={22} />
            In-App Pop-up &amp; Promotional Offer Manager
          </h2>
          <p className="text-xs text-muted mt-0.5">
            Configure dynamic broadcast popups, special festive deals (e.g. ₹19/month), and auto-redeemable coupon codes.
          </p>
        </div>
        <div className="flex items-center gap-2">
          <button
            onClick={fetchConfig}
            disabled={loading}
            className="p-2 rounded-xl bg-surface hover:bg-input border border-subtle text-secondary hover:text-main text-xs font-semibold transition"
          >
            <RefreshCw size={14} className={loading ? "animate-spin" : ""} />
          </button>
          <button
            onClick={handleSave}
            disabled={saving}
            className="px-4 py-2 bg-primary hover:bg-primary/90 text-white rounded-xl text-xs font-bold transition flex items-center gap-2 shadow-md"
          >
            <Save size={14} />
            <span>{saving ? "Publishing..." : "Save & Broadcast"}</span>
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
        {/* Left Column: Form Configuration (7 cols) */}
        <div className="lg:col-span-7 space-y-5 bg-card p-5 md:p-6 rounded-2xl border border-subtle shadow-sm">
          {/* Active Status Switch */}
          <div className="flex items-center justify-between p-4 rounded-xl bg-surface border border-subtle">
            <div>
              <div className="text-sm font-bold text-main flex items-center gap-2">
                <span className={`w-2.5 h-2.5 rounded-full ${config.isActive ? "bg-emerald-500 animate-pulse" : "bg-zinc-400"}`} />
                Pop-up Broadcast Status
              </div>
              <p className="text-xs text-muted mt-0.5">
                {config.isActive 
                  ? "Active — All passengers visiting the platform will see this promotional popup."
                  : "Inactive — The popup is paused and hidden from visitors."}
              </p>
            </div>
            <label className="relative inline-flex items-center cursor-pointer">
              <input
                type="checkbox"
                checked={config.isActive}
                onChange={(e) => setConfig({ ...config, isActive: e.target.checked })}
                className="sr-only peer"
              />
              <div className="w-11 h-6 bg-input peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-emerald-500"></div>
            </label>
          </div>

          {/* Offer Title & Badge */}
          <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
            <div className="sm:col-span-2 space-y-1">
              <label className="text-xs font-bold text-muted uppercase tracking-wider">Offer Title</label>
              <input
                type="text"
                value={config.title}
                onChange={(e) => setConfig({ ...config, title: e.target.value })}
                placeholder="e.g. Festive Travel Freedom Offer"
                className="w-full bg-input border border-subtle rounded-xl px-3 py-2 text-xs text-main font-medium focus:outline-none focus:border-strong transition"
              />
            </div>
            <div className="space-y-1">
              <label className="text-xs font-bold text-muted uppercase tracking-wider">Badge Tag</label>
              <input
                type="text"
                value={config.badgeText}
                onChange={(e) => setConfig({ ...config, badgeText: e.target.value })}
                placeholder="e.g. SPECIAL PROMO"
                className="w-full bg-input border border-subtle rounded-xl px-3 py-2 text-xs text-main font-bold uppercase focus:outline-none focus:border-strong transition"
              />
            </div>
          </div>

          {/* Subtitle / Description */}
          <div className="space-y-1">
            <label className="text-xs font-bold text-muted uppercase tracking-wider">Subtitle / Pitch</label>
            <textarea
              rows={3}
              value={config.subtitle}
              onChange={(e) => setConfig({ ...config, subtitle: e.target.value })}
              placeholder="Explain the offer benefits..."
              className="w-full bg-input border border-subtle rounded-xl px-3 py-2 text-xs text-main font-medium focus:outline-none focus:border-strong transition resize-none"
            />
          </div>

          {/* Pricing & Coupon Settings */}
          <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
            <div className="space-y-1">
              <label className="text-xs font-bold text-emerald-500 uppercase tracking-wider">Offer Price</label>
              <input
                type="text"
                value={config.offerPrice}
                onChange={(e) => setConfig({ ...config, offerPrice: e.target.value })}
                placeholder="₹19"
                className="w-full bg-input border border-emerald-500/30 rounded-xl px-3 py-2 text-xs text-main font-black font-mono focus:outline-none focus:border-emerald-500 transition"
              />
            </div>
            <div className="space-y-1">
              <label className="text-xs font-bold text-muted uppercase tracking-wider">Original Price</label>
              <input
                type="text"
                value={config.originalPrice}
                onChange={(e) => setConfig({ ...config, originalPrice: e.target.value })}
                placeholder="₹49"
                className="w-full bg-input border border-subtle rounded-xl px-3 py-2 text-xs text-muted line-through font-mono focus:outline-none focus:border-strong transition"
              />
            </div>
            <div className="space-y-1">
              <label className="text-xs font-bold text-indigo-400 uppercase tracking-wider">Coupon Code</label>
              <input
                type="text"
                value={config.couponCode}
                onChange={(e) => setConfig({ ...config, couponCode: e.target.value.toUpperCase() })}
                placeholder="OFFER19"
                className="w-full bg-input border border-indigo-500/30 rounded-xl px-3 py-2 text-xs text-indigo-400 font-black uppercase font-mono focus:outline-none focus:border-indigo-500 transition"
              />
            </div>
            <div className="space-y-1">
              <label className="text-xs font-bold text-muted uppercase tracking-wider">Duration (Days)</label>
              <input
                type="number"
                min={1}
                max={365}
                value={config.durationDays}
                onChange={(e) => setConfig({ ...config, durationDays: Number(e.target.value) })}
                className="w-full bg-input border border-subtle rounded-xl px-3 py-2 text-xs text-main font-bold font-mono focus:outline-none focus:border-strong transition"
              />
            </div>
          </div>

          {/* Target Plan Type */}
          <div className="space-y-1">
            <label className="text-xs font-bold text-muted uppercase tracking-wider">Target Plan Granted on Claim</label>
            <select
              value={config.planType}
              onChange={(e) => setConfig({ ...config, planType: e.target.value })}
              className="w-full bg-input border border-subtle rounded-xl px-3 py-2 text-xs text-main font-semibold focus:outline-none focus:border-strong transition"
            >
              <option value="safar_pro_30d">Pro Monthly (30 Days Unlimited AI &amp; Features)</option>
              <option value="safar_pro_7d">AI Pass (7 Days)</option>
              <option value="safar_pro_1d">1-Day AI Pass</option>
              <option value="safar_pro_30m">Blitz Pro (30 Min)</option>
              <option value="safar_pro_90d">Pro Yearly (365 Days)</option>
            </select>
          </div>

          {/* Feature List (One per line) */}
          <div className="space-y-1">
            <label className="text-xs font-bold text-muted uppercase tracking-wider">Features Bullet Points (one per line)</label>
            <textarea
              rows={4}
              value={featuresText}
              onChange={(e) => setFeaturesText(e.target.value)}
              className="w-full bg-input border border-subtle rounded-xl px-3 py-2 text-xs text-main font-medium focus:outline-none focus:border-strong transition resize-none font-mono"
            />
          </div>

          {/* Action CTA Button Text */}
          <div className="space-y-1">
            <label className="text-xs font-bold text-muted uppercase tracking-wider">CTA Button Text</label>
            <input
              type="text"
              value={config.ctaText}
              onChange={(e) => setConfig({ ...config, ctaText: e.target.value })}
              placeholder="e.g. Claim 1 Month Pro for ₹19"
              className="w-full bg-input border border-subtle rounded-xl px-3 py-2 text-xs text-main font-bold focus:outline-none focus:border-strong transition"
            />
          </div>
        </div>

        {/* Right Column: Live Modal Preview (5 cols) */}
        <div className="lg:col-span-5 space-y-3">
          <div className="flex items-center gap-1.5 text-xs font-bold text-muted uppercase tracking-wider">
            <Eye size={14} className="text-primary" /> Live Visitor Preview
          </div>

          {/* Interactive Modal Mockup */}
          <div className="relative rounded-3xl bg-gradient-to-b from-card to-card/90 border border-primary/20 p-6 shadow-2xl overflow-hidden">
            {/* Ambient glow */}
            <div className="absolute top-0 right-0 w-40 h-40 bg-primary/10 rounded-full blur-2xl pointer-events-none" />
            <div className="absolute bottom-0 left-0 w-40 h-40 bg-amber-500/10 rounded-full blur-2xl pointer-events-none" />

            {/* Modal Content */}
            <div className="relative space-y-4">
              {/* Badge & Close button mockup */}
              <div className="flex items-center justify-between">
                <span className="px-2.5 py-1 rounded-full text-[10px] font-black uppercase tracking-wider bg-primary/15 text-primary border border-primary/30">
                  {config.badgeText || "SPECIAL OFFER"}
                </span>
                <span className="text-muted text-xs font-mono">Preview</span>
              </div>

              {/* Title & Subtitle */}
              <div>
                <h3 className="text-lg font-black text-main leading-tight">
                  {config.title || "Offer Title"}
                </h3>
                <p className="text-xs text-muted mt-1 leading-relaxed">
                  {config.subtitle}
                </p>
              </div>

              {/* Price Callout Banner */}
              <div className="p-3.5 rounded-2xl bg-gradient-to-r from-emerald-500/15 to-primary/15 border border-emerald-500/30 flex items-center justify-between">
                <div>
                  <div className="text-[10px] font-bold text-muted uppercase">Special Festive Price</div>
                  <div className="flex items-baseline gap-2 mt-0.5">
                    <span className="text-2xl font-black text-emerald-500 font-mono">{config.offerPrice}</span>
                    <span className="text-xs text-muted line-through font-mono">{config.originalPrice}</span>
                    <span className="text-[11px] font-bold text-main">/ {config.durationDays} Days</span>
                  </div>
                </div>
                <div className="text-right">
                  <span className="text-[10px] text-muted block">Promo Code:</span>
                  <span className="px-2 py-0.5 rounded-md bg-card border border-indigo-500/40 text-indigo-400 font-mono font-black text-xs">
                    {config.couponCode || "OFFER"}
                  </span>
                </div>
              </div>

              {/* Features bullets */}
              <div className="space-y-2 py-1">
                {featuresText.split("\n").filter(Boolean).map((feat, idx) => (
                  <div key={idx} className="flex items-center gap-2 text-xs text-secondary">
                    <CheckCircle2 size={14} className="text-emerald-500 shrink-0" />
                    <span>{feat}</span>
                  </div>
                ))}
              </div>

              {/* Claim Button */}
              <button
                type="button"
                className="w-full py-3 bg-gradient-to-r from-emerald-500 via-primary to-indigo-600 text-white rounded-xl text-xs font-black uppercase tracking-wider shadow-lg shadow-primary/25 hover:opacity-95 transition flex items-center justify-center gap-2"
              >
                <Zap size={14} />
                <span>{config.ctaText || "Claim Offer Now"}</span>
              </button>

              <div className="text-[10px] text-center text-muted">
                Applies coupon code <strong className="text-main font-mono">{config.couponCode}</strong> automatically on click.
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Diwali Email Campaign Dispatcher Section */}
      <div className="rounded-3xl border border-amber-500/30 bg-gradient-to-br from-amber-500/5 via-card to-card p-6 shadow-xl space-y-6">
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 border-b border-subtle pb-4">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-2xl bg-amber-500/20 border border-amber-500/30 flex items-center justify-center text-xl shrink-0">
              🪔
            </div>
            <div>
              <h3 className="text-base font-bold text-main flex items-center gap-2">
                Diwali Promotional Email Campaign Broadcaster
                <span className="px-2 py-0.5 rounded-full text-[10px] font-black uppercase tracking-wider bg-amber-500/20 text-amber-400 border border-amber-500/30">
                  543 Users
                </span>
              </h3>
              <p className="text-xs text-muted">
                Broadcast festive special offer (1 Month Trayago Pro for ₹35 with code OFFER35) to all verified registered users.
              </p>
            </div>
          </div>
        </div>

        {/* Campaign Overview Grid */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          <div className="p-4 rounded-2xl bg-input/50 border border-subtle space-y-2">
            <span className="text-[10px] font-bold text-muted uppercase tracking-wider">Campaign Target</span>
            <div className="text-2xl font-black text-main font-mono">543 Users</div>
            <p className="text-[11px] text-muted">100% verified emails in production Supabase users database.</p>
          </div>

          <div className="p-4 rounded-2xl bg-input/50 border border-subtle space-y-2">
            <span className="text-[10px] font-bold text-muted uppercase tracking-wider">Offer &amp; Pricing</span>
            <div className="flex items-baseline gap-2">
              <span className="text-2xl font-black text-amber-400 font-mono">₹35</span>
              <span className="text-xs text-muted line-through font-mono">₹49</span>
              <span className="text-xs font-bold text-muted">/ 30 Days</span>
            </div>
            <p className="text-[11px] text-muted">Promo Code: <strong className="text-main font-mono">OFFER35</strong></p>
          </div>

          <div className="p-4 rounded-2xl bg-input/50 border border-subtle space-y-2">
            <span className="text-[10px] font-bold text-muted uppercase tracking-wider">Email Banner Asset</span>
            <div className="text-xs font-bold text-emerald-400 flex items-center gap-1.5">
              <CheckCircle2 size={14} /> Deployed &amp; Live (16:9)
            </div>
            <a
              href="https://www.trayago.in/branding/trayago-diwali-2026.jpg"
              target="_blank"
              rel="noreferrer"
              className="text-[11px] text-primary hover:underline truncate block"
            >
              trayago-diwali-2026.jpg &rarr;
            </a>
          </div>
        </div>

        {/* Action Controls */}
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-4 pt-2">
          {/* Step 1: Test Email */}
          <div className="p-4 rounded-2xl bg-card border border-subtle space-y-3">
            <div className="flex items-center gap-2">
              <span className="w-5 h-5 rounded-full bg-primary/20 text-primary text-xs font-bold flex items-center justify-center">1</span>
              <h4 className="text-xs font-bold text-main uppercase tracking-wider">Step 1: Send Test Email to Verify Layout</h4>
            </div>
            <p className="text-xs text-muted">
              Sends an immediate preview email with all branding, images, buttons, and promo codes to your personal inbox.
            </p>
            <div className="flex items-center gap-2">
              <input
                type="email"
                value={testEmail}
                onChange={(e) => setTestEmail(e.target.value)}
                placeholder="your-email@gmail.com"
                className="flex-1 bg-input border border-subtle rounded-xl px-3 py-2 text-xs text-main font-semibold focus:outline-none focus:border-strong transition"
              />
              <button
                type="button"
                onClick={handleSendTestEmail}
                disabled={testSending || !testEmail}
                className="px-4 py-2 bg-primary hover:bg-primary/90 text-primary-foreground rounded-xl text-xs font-bold transition flex items-center gap-2 shrink-0 disabled:opacity-50"
              >
                {testSending ? <RefreshCw size={13} className="animate-spin" /> : <Sparkles size={13} />}
                <span>{testSending ? "Sending..." : "Send Test Email"}</span>
              </button>
            </div>
          </div>

          {/* Step 2: Mass Broadcast */}
          <div className="p-4 rounded-2xl bg-card border border-amber-500/30 space-y-3">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-2">
                <span className="w-5 h-5 rounded-full bg-amber-500/20 text-amber-400 text-xs font-bold flex items-center justify-center">2</span>
                <h4 className="text-xs font-bold text-amber-400 uppercase tracking-wider">Step 2: Broadcast Campaign</h4>
              </div>
              <span className="text-[10px] font-bold px-2.5 py-0.5 rounded-full bg-emerald-500/20 text-emerald-400 border border-emerald-500/30">
                359 / 542 Delivered
              </span>
            </div>

            <p className="text-xs text-muted">
              Safe 7 emails/second dispatch compliant with Resend Pro burst rate limits.
            </p>

            <div className="space-y-2 pt-1">
              {/* PRIMARY RESUME BUTTON (Remaining 184 users) */}
              <button
                type="button"
                onClick={() => handleBroadcastAll(359)}
                disabled={broadcasting}
                className="w-full py-3 bg-gradient-to-r from-amber-500 via-orange-500 to-amber-600 hover:from-amber-400 hover:to-orange-500 text-slate-950 font-black rounded-xl text-xs uppercase tracking-wider shadow-lg shadow-amber-500/25 transition flex items-center justify-center gap-2 disabled:opacity-50 cursor-pointer active:scale-98"
              >
                {broadcasting ? <RefreshCw size={14} className="animate-spin" /> : <Flame size={14} />}
                <span>{broadcasting ? "Broadcasting in Progress..." : "⚡ Resume Remaining 184 Users (From User #360)"}</span>
              </button>

              {/* SECONDARY RE-BROADCAST ALL BUTTON */}
              <button
                type="button"
                onClick={() => handleBroadcastAll(0)}
                disabled={broadcasting}
                className="w-full py-2 bg-input/80 hover:bg-input border border-subtle text-muted hover:text-main font-bold rounded-xl text-[11px] transition flex items-center justify-center gap-1.5 disabled:opacity-50 cursor-pointer"
              >
                <RefreshCw size={12} />
                <span>Re-Broadcast All 543 Users (From Beginning)</span>
              </button>
            </div>
          </div>
        </div>

        {/* Broadcast Live Status Report */}
        {broadcastResult && (
          <div className="p-4 rounded-2xl bg-emerald-500/10 border border-emerald-500/30 text-xs space-y-3 animate-fade-in">
            <div className="flex items-center justify-between font-bold text-emerald-400">
              <span className="flex items-center gap-1.5">
                <CheckCircle2 size={16} /> Broadcast Successfully Finished!
              </span>
              <span className="font-mono">
                {broadcastResult.sentCount} / {broadcastResult.totalRecipients} Delivered
              </span>
            </div>
            <p className="text-muted leading-relaxed">
              {broadcastResult.message}
            </p>
            {broadcastResult.sentCount < broadcastResult.totalRecipients && (
              <div className="pt-2 border-t border-emerald-500/20 flex flex-col sm:flex-row items-start sm:items-center justify-between gap-2">
                <span className="text-amber-400 font-medium">
                  {broadcastResult.totalRecipients - broadcastResult.sentCount} users remaining (provider daily quota limit reached).
                </span>
                <button
                  type="button"
                  onClick={() => handleBroadcastAll(broadcastResult.sentCount)}
                  disabled={broadcasting}
                  className="px-3.5 py-1.5 bg-amber-500 hover:bg-amber-400 text-slate-950 font-black rounded-lg text-[11px] transition flex items-center gap-1.5 cursor-pointer disabled:opacity-50"
                >
                  <Flame size={12} />
                  <span>Resume Remaining ({broadcastResult.totalRecipients - broadcastResult.sentCount} Users)</span>
                </button>
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
}
