"use client";

import React, { useEffect, useState, useCallback } from "react";
import { 
  Globe, Search, TrendingUp, AlertTriangle, ArrowRight, 
  RefreshCw, MapPin, Zap, Flame, Filter, ChevronRight
} from "lucide-react";
import { fetchWithAuth } from "@/lib/fetchWithAuth";

interface SearchDemandPanelProps {
  api: string;
  getAuthHeaders: () => Record<string, string>;
  triggerToast: (msg: string, type: "success" | "error" | "info") => void;
}

export function SearchDemandPanel({ api, getAuthHeaders, triggerToast }: SearchDemandPanelProps) {
  const [data, setData] = useState<{
    topRoutes: any[];
    recentSearches: any[];
    highDemandUnserved: any[];
    totalSearches: number;
  }>({
    topRoutes: [],
    recentSearches: [],
    highDemandUnserved: [],
    totalSearches: 0
  });

  const [loading, setLoading] = useState<boolean>(true);
  const [filterMode, setFilterMode] = useState<"ALL" | "HOT_ROUTES" | "UNSERVED">("ALL");

  const fetchData = useCallback(async () => {
    try {
      setLoading(true);
      const res = await fetchWithAuth(`${api}/api/admin/search-demand`, {
        headers: getAuthHeaders()
      });
      if (res.ok) {
        const json = await res.json();
        if (json.success && json.data) {
          setData(json.data);
        }
      }
    } catch (err: any) {
      triggerToast("Failed to fetch search demand intelligence", "error");
    } finally {
      setLoading(false);
    }
  }, [api, getAuthHeaders, triggerToast]);

  useEffect(() => {
    fetchData();
  }, [fetchData]);

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 border-b border-subtle pb-4">
        <div>
          <h2 className="text-xl font-bold flex items-center gap-2 text-main">
            <Globe className="text-indigo-500" size={22} />
            Search &amp; Route Demand Intelligence
          </h2>
          <p className="text-xs text-muted mt-0.5">
            Identify high-volume passenger travel corridors, unserved zero-direct-train routes &amp; conversion bottlenecks.
          </p>
        </div>
        <button
          onClick={fetchData}
          disabled={loading}
          className="px-3.5 py-2 rounded-xl bg-surface hover:bg-input border border-subtle text-secondary hover:text-main text-xs font-semibold transition flex items-center gap-2 shadow-sm w-fit"
        >
          <RefreshCw size={13} className={loading ? "animate-spin text-primary" : ""} />
          <span>Refresh Intelligence</span>
        </button>
      </div>

      {/* KPI Bento Row */}
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
        <div className="p-5 rounded-2xl bg-card border border-subtle shadow-sm">
          <div className="flex items-center justify-between text-xs text-muted mb-1 font-semibold uppercase tracking-wider">
            <span>Total Queries Logged</span>
            <Search size={14} className="text-indigo-400" />
          </div>
          <div className="text-3xl font-black text-main font-mono mt-2">
            {data.totalSearches.toLocaleString()}
          </div>
          <div className="text-xs text-muted mt-1">Platform origin-destination intent</div>
        </div>

        <div className="p-5 rounded-2xl bg-card border border-subtle shadow-sm">
          <div className="flex items-center justify-between text-xs text-muted mb-1 font-semibold uppercase tracking-wider">
            <span>Top Monitored Corridors</span>
            <Flame size={14} className="text-amber-500" />
          </div>
          <div className="text-3xl font-black text-amber-500 font-mono mt-2">
            {data.topRoutes.length}
          </div>
          <div className="text-xs text-muted mt-1">High-density passenger routes</div>
        </div>

        <div className="p-5 rounded-2xl bg-gradient-to-br from-rose-500/10 via-card to-card border border-rose-500/25 shadow-sm">
          <div className="flex items-center justify-between text-xs text-muted mb-1 font-semibold uppercase tracking-wider">
            <span className="text-rose-500">Unserved / Split Routes</span>
            <AlertTriangle size={14} className="text-rose-500" />
          </div>
          <div className="text-3xl font-black text-main font-mono mt-2">
            {data.highDemandUnserved.length}
          </div>
          <div className="text-xs text-secondary mt-1">Direct trains full or missing (Split Journey Goldmines)</div>
        </div>
      </div>

      {/* Top Routes Table */}
      <div className="bg-card rounded-2xl border border-subtle shadow-sm overflow-hidden">
        <div className="p-4 border-b border-subtle flex items-center justify-between bg-surface/50">
          <div className="text-xs font-bold uppercase tracking-wider text-main flex items-center gap-2">
            <Flame size={14} className="text-amber-500" /> Top Searched Travel Corridors
          </div>
          <div className="text-xs text-muted">
            Ranked by search volume &amp; passenger intent
          </div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-left text-xs">
            <thead>
              <tr className="border-b border-subtle bg-surface/80 text-muted uppercase font-bold text-[10px] tracking-wider">
                <th className="py-3 px-4">Rank</th>
                <th className="py-3 px-4">Origin Station</th>
                <th className="py-3 px-4">Destination Station</th>
                <th className="py-3 px-4">Search Volume</th>
                <th className="py-3 px-4">Demand Level</th>
                <th className="py-3 px-4">Opportunity</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-subtle font-medium">
              {data.topRoutes.map((route, idx) => (
                <tr key={`${route.source}-${route.destination}-${idx}`} className="hover:bg-surface/50 transition">
                  <td className="py-3 px-4 font-mono font-bold text-muted">
                    #{idx + 1}
                  </td>
                  <td className="py-3 px-4 font-bold text-main">
                    {route.source}
                  </td>
                  <td className="py-3 px-4 font-bold text-main">
                    {route.destination}
                  </td>
                  <td className="py-3 px-4 font-mono font-black text-indigo-400 text-sm">
                    {route.count} <span className="text-xs font-normal text-muted">searches</span>
                  </td>
                  <td className="py-3 px-4">
                    {route.count > 100 ? (
                      <span className="px-2 py-0.5 rounded-full bg-amber-500/15 text-amber-500 border border-amber-500/30 text-[10px] font-bold uppercase">
                        High Intent
                      </span>
                    ) : (
                      <span className="px-2 py-0.5 rounded-full bg-blue-500/10 text-blue-400 border border-blue-500/20 text-[10px] font-bold uppercase">
                        Steady
                      </span>
                    )}
                  </td>
                  <td className="py-3 px-4 text-secondary">
                    <span className="text-[11px] font-semibold text-emerald-500 flex items-center gap-1">
                      <Zap size={11} /> Ready for Split Journey Pre-Caching
                    </span>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* Recent Search Activity Log */}
      <div className="bg-card rounded-2xl border border-subtle shadow-sm p-5">
        <div className="text-xs font-bold uppercase tracking-wider text-muted mb-4 flex items-center gap-2">
          <TrendingUp size={14} className="text-indigo-400" /> Recent Search Stream (Last 30 Queries)
        </div>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3">
          {data.recentSearches.map((s, idx) => (
            <div key={idx} className="p-3 rounded-xl bg-surface border border-subtle flex items-center justify-between text-xs">
              <div>
                <div className="font-bold text-main flex items-center gap-1.5">
                  <span>{s.source}</span>
                  <ArrowRight size={11} className="text-muted" />
                  <span>{s.destination}</span>
                </div>
                <div className="text-[10px] text-muted mt-0.5">
                  Date: {s.date || "Anytime"} &bull; Trains: {s.direct_train_count ?? 1}
                </div>
              </div>
              {s.split_used && (
                <span className="px-1.5 py-0.5 rounded bg-purple-500/15 text-purple-400 border border-purple-500/30 font-mono text-[9px] font-bold">
                  SPLIT
                </span>
              )}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}
