import React, { useEffect, useState, useCallback } from "react";
import {
  Users, Search, RefreshCw, Unlock, Lock, CrownIcon, Zap,
  ChevronUp, ChevronDown, LogOut, CheckCircle2, XCircle, UserX, Loader2, X, User
} from "lucide-react";
import { fetchWithAuth } from "@/lib/fetchWithAuth";
import { User360Drawer } from "./User360Drawer";

const PLAN_COLORS: Record<string, string> = {
  free: "bg-zinc-100 dark:bg-zinc-700 text-zinc-600 dark:text-zinc-100 border border-zinc-200 dark:border-zinc-500",
  paid: "bg-yellow-100 dark:bg-yellow-900/40 text-yellow-800 dark:text-yellow-300 border border-yellow-300 dark:border-yellow-700/30",
  safar_pro_30m: "bg-purple-100 dark:bg-purple-900/40 text-purple-800 dark:text-purple-300 border border-purple-300 dark:border-purple-700/30",
  safar_pro_1d: "bg-purple-100 dark:bg-purple-900/40 text-purple-800 dark:text-purple-300 border border-purple-300 dark:border-purple-700/30",
  safar_pro_7d: "bg-indigo-100 dark:bg-indigo-900/40 text-indigo-800 dark:text-indigo-300 border border-indigo-300 dark:border-indigo-700/30",
  safar_pro_30d: "bg-blue-100 dark:bg-blue-900/40 text-blue-800 dark:text-blue-300 border border-blue-300 dark:border-blue-700/30",
  admin: "bg-red-100 dark:bg-red-900/40 text-red-800 dark:text-red-300 border border-red-300 dark:border-red-700/30",
};

// ─── Plan Change Modal ────────────────────────────────────────────────────────
function PlanModal({ userId, currentPlan, api, getAuthHeaders, onClose, onSuccess }: {
  userId: string; currentPlan: string; api: string; getAuthHeaders: () => Record<string, string>; onClose: () => void; onSuccess: (msg: string) => void;
}) {
  const [planType, setPlanType] = useState(currentPlan);
  const [durationDays, setDurationDays] = useState(30);
  const [loading, setLoading] = useState(false);

  const plans = [
    { value: "free", label: "Free" },
    { value: "safar_pro_30m", label: "Blitz Pro 30 Min" },
    { value: "safar_pro_7d", label: "AI Pass (7 Days)" },
    { value: "safar_pro_30d", label: "Pro Monthly (30 Days)" },
    { value: "safar_pro_90d", label: "Pro Yearly (365 Days)" },
    { value: "safar_pro", label: "Legacy Safar Pro (30 Days)" },
    { value: "beta", label: "Beta Tester" },
    { value: "paid", label: "Legacy Paid" },
    { value: "admin", label: "Admin" },
  ];

  const handleSubmit = async () => {
    setLoading(true);
    try {
      const res = await fetchWithAuth(`${api}/api/admin/users/${userId}/change-plan`, {
        method: "POST",
        headers: { "Content-Type": "application/json", ...getAuthHeaders() },
        body: JSON.stringify({ planType, durationDays: planType !== "free" ? durationDays : undefined }),
      });
      const json = await res.json();
      if (json.success) { onSuccess(json.message); onClose(); }
    } finally { setLoading(false); }
  };

  return (
    <div className="fixed inset-0 z-50 bg-black/75 flex items-center justify-center p-4 backdrop-blur-sm">
      <div className="bg-card border border-subtle rounded-2xl p-6 w-full max-w-md shadow-2xl">
        <h3 className="text-lg font-bold mb-4 flex items-center gap-2 text-main"><CrownIcon size={18} className="text-yellow-400" /> Change Plan</h3>
        <div className="space-y-4">
          <div>
            <label className="text-xs text-muted mb-1 block">Plan Type</label>
            <select value={planType} onChange={e => setPlanType(e.target.value)}
              className="w-full bg-input border border-subtle rounded-lg px-3 py-2 text-sm text-main focus:outline-none focus:border-strong transition">
              {plans.map(p => <option key={p.value} value={p.value} className="bg-card text-main">{p.label}</option>)}
            </select>
          </div>
          {planType !== "free" && (
            <div>
              <label className="text-xs text-muted mb-1 block">Duration (days)</label>
              <input type="number" min={1} max={365} value={durationDays} onChange={e => setDurationDays(Number(e.target.value))}
                className="w-full bg-input border border-subtle rounded-lg px-3 py-2 text-sm text-main focus:outline-none focus:border-strong transition" />
            </div>
          )}
          <div className="flex gap-3 pt-2">
            <button onClick={onClose} className="flex-1 py-2 rounded-lg bg-input hover:bg-input/80 text-secondary text-sm transition border border-subtle">Cancel</button>
            <button onClick={handleSubmit} disabled={loading}
              className="flex-1 py-2 rounded-lg bg-indigo-600 hover:bg-indigo-500 text-white text-sm font-medium transition flex items-center justify-center gap-2">
              {loading && <Loader2 size={14} className="animate-spin" />} Apply
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

// ─── Quota Override Modal ───────────────────────────────────────────────────
function QuotaModal({ userId, currentSearches, currentPnr, currentLive, api, getAuthHeaders, onClose, onSuccess }: {
  userId: string;
  currentSearches: number;
  currentPnr: number;
  currentLive: number;
  api: string;
  getAuthHeaders: () => Record<string, string>;
  onClose: () => void;
  onSuccess: (msg: string) => void;
}) {
  const [customSearches, setCustomSearches] = useState<string>("5");
  const [customPnr, setCustomPnr] = useState<string>("3");
  const [customLive, setCustomLive] = useState<string>("3");
  const [durationDays, setDurationDays] = useState<number>(30);
  const [loading, setLoading] = useState(false);

  const handleSubmit = async () => {
    setLoading(true);
    try {
      const res = await fetchWithAuth(`${api}/api/admin/users/${userId}/override-quota`, {
        method: "POST",
        headers: { "Content-Type": "application/json", ...getAuthHeaders() },
        body: JSON.stringify({
          customSearches: customSearches !== "" ? parseInt(customSearches, 10) : null,
          customPnr: customPnr !== "" ? parseInt(customPnr, 10) : null,
          customLive: customLive !== "" ? parseInt(customLive, 10) : null,
          durationDays: durationDays
        }),
      });
      const json = await res.json();
      if (json.success) {
        onSuccess(json.message);
        onClose();
      } else {
        alert(json.error || "Failed to configure overrides");
      }
    } catch {
      alert("Network error occurred");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 bg-black/75 flex items-center justify-center p-4 backdrop-blur-sm">
      <div className="bg-card border border-subtle rounded-2xl p-6 w-full max-w-md shadow-2xl">
        <h3 className="text-lg font-bold mb-4 flex items-center gap-2 text-indigo-655 dark:text-indigo-400"><Zap size={18} /> Custom Quota Override</h3>
        <div className="space-y-4">
          <div>
            <label className="text-xs text-muted mb-1 block">Custom Searches Limit</label>
            <input type="number" min={0} value={customSearches} onChange={e => setCustomSearches(e.target.value)}
              className="w-full bg-input border border-subtle rounded-lg px-3 py-2 text-sm text-main focus:outline-none focus:border-strong transition" />
          </div>
          <div>
            <label className="text-xs text-muted mb-1 block">Custom PNR Limit</label>
            <input type="number" min={0} value={customPnr} onChange={e => setCustomPnr(e.target.value)}
              className="w-full bg-input border border-subtle rounded-lg px-3 py-2 text-sm text-main focus:outline-none focus:border-strong transition" />
          </div>
          <div>
            <label className="text-xs text-muted mb-1 block">Custom Live Limit</label>
            <input type="number" min={0} value={customLive} onChange={e => setCustomLive(e.target.value)}
              className="w-full bg-input border border-subtle rounded-lg px-3 py-2 text-sm text-main focus:outline-none focus:border-strong transition" />
          </div>
          <div>
            <label className="text-xs text-muted mb-1 block">Duration (days)</label>
            <input type="number" min={1} max={365} value={durationDays} onChange={e => setDurationDays(Number(e.target.value))}
              className="w-full bg-input border border-subtle rounded-lg px-3 py-2 text-sm text-main focus:outline-none focus:border-strong transition" />
          </div>
          <div className="flex gap-3 pt-2">
            <button onClick={onClose} className="flex-1 py-2 rounded-lg bg-input hover:bg-input/80 text-secondary text-sm transition border border-subtle">Cancel</button>
            <button onClick={handleSubmit} disabled={loading}
              className="flex-1 py-2 rounded-lg bg-indigo-600 hover:bg-indigo-500 text-white text-sm font-medium transition flex items-center justify-center gap-2">
              {loading && <Loader2 size={14} className="animate-spin" />} Apply
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

// ─── User Row ─────────────────────────────────────────────────────────────────
function UserRow({
  user,
  checked,
  currentUserId,
  onToggleCheck,
  onAction
}: {
  user: any;
  checked: boolean;
  currentUserId: string;
  onToggleCheck: (userId: string) => void;
  onAction: (type: string, userId: string, extra?: any) => void;
}) {
  const [expanded, setExpanded] = useState(false);
  const [creditsChange, setCreditsChange] = useState("");
  const [adjusting, setAdjusting] = useState(false);
  const [terminating, setTerminating] = useState(false);
  const planClass = PLAN_COLORS[user.planType] || PLAN_COLORS.free;

  // Self Protection Guard
  const isSelf = user.id === currentUserId;
  const isDisabledAction = user.isAdmin || isSelf;

  const handleAdjustCredits = async () => {
    const val = parseInt(creditsChange, 10);
    if (isNaN(val)) return;
    setAdjusting(true);
    try {
      await onAction("adjust-credits", user.id, val);
      setCreditsChange("");
    } finally {
      setAdjusting(false);
    }
  };

  const handleTerminateSessions = async () => {
    setTerminating(true);
    try {
      await onAction("terminate-sessions", user.id);
    } finally {
      setTerminating(false);
    }
  };

  return (
    <>
      <tr className={`border-b border-subtle hover:bg-input/20 transition-colors ${user.isBlocked ? "opacity-60" : ""}`}>
        <td className="px-4 py-3 w-10">
          <input
            type="checkbox"
            checked={checked}
            onChange={() => onToggleCheck(user.id)}
            disabled={isDisabledAction}
            className="rounded border-subtle bg-input text-indigo-600 focus:ring-indigo-500/50 w-4 h-4 cursor-pointer disabled:opacity-30 disabled:cursor-not-allowed"
          />
        </td>
        <td className="px-4 py-3">
          <div className="flex flex-col">
            <div className="flex items-center gap-1.5 flex-wrap">
              <span className="text-sm font-medium text-main truncate max-w-[200px]">{user.email}</span>
              {user.isAdmin && (
                <span className="text-[9px] font-bold px-1.5 py-0.5 rounded bg-indigo-50 dark:bg-indigo-950/40 border border-indigo-200 dark:border-indigo-900/30 text-indigo-650 dark:text-indigo-400">
                  ADMIN
                </span>
              )}
              {isSelf && <span className="text-[10px] text-indigo-650 dark:text-indigo-400 bg-indigo-50 dark:bg-indigo-950/40 border border-indigo-200 dark:border-indigo-900/30 px-1.5 py-0.5 rounded font-bold">YOU</span>}
            </div>
            <div className="flex items-center gap-2 text-xs text-muted font-mono">
              <span>{user.id.slice(0, 8)}…</span>
              {(user.deviceType || user.platform) && (
                <span className="text-[10px] px-1.5 py-0.5 rounded bg-surface border border-subtle text-secondary font-sans font-medium">
                  {user.deviceType === 'desktop' ? '💻 PC' : user.deviceType === 'tablet' ? '📟 Tablet' : '📱 Mobile'}
                  {user.platform ? ` (${user.platform})` : ''}
                </span>
              )}
            </div>
          </div>
        </td>
        <td className="px-4 py-3">
          <span className={`text-[10px] px-2 py-0.5 rounded-full font-bold uppercase ${planClass}`}>{user.planType}</span>
        </td>
        <td className="px-4 py-3 text-xs text-muted">{new Date(user.createdAt).toLocaleDateString("en-IN")}</td>
        <td className="px-4 py-3">
          <div className="flex items-center gap-2 text-xs text-secondary">
            <span title="Searches">{user.dailySearchCount}S</span>
            <span className="text-muted">·</span>
            <span title="PNR">{user.dailyPnrCount}P</span>
            <span className="text-muted">·</span>
            <span title="Live">{user.dailyLiveCount}L</span>
          </div>
        </td>
        <td className="px-4 py-3">
          {user.isBlocked ? (
            <span className="flex items-center gap-1 text-xs text-red-655 dark:text-red-400 font-medium"><XCircle size={12} /> Blocked</span>
          ) : (
            <span className="flex items-center gap-1 text-xs text-emerald-600 dark:text-emerald-400 font-medium"><CheckCircle2 size={12} /> Active</span>
          )}
        </td>
        <td className="px-4 py-3">
          <div className="flex items-center gap-1">
            {user.isBlocked ? (
              <button onClick={() => onAction("unblock", user.id)} title="Unblock" disabled={isDisabledAction}
                className="p-1.5 rounded-lg bg-emerald-50 dark:bg-emerald-950/30 hover:bg-emerald-100 dark:hover:bg-emerald-900/40 border border-emerald-200 dark:border-emerald-800/30 text-emerald-700 dark:text-emerald-400 transition disabled:opacity-30 disabled:hover:bg-emerald-50">
                <Unlock size={13} />
              </button>
            ) : (
              <button onClick={() => onAction("block", user.id)} title="Block" disabled={isDisabledAction}
                className="p-1.5 rounded-lg bg-red-50 dark:bg-red-950/20 hover:bg-red-100 dark:hover:bg-red-900/4 border border-red-200 dark:border-red-800/30 text-red-655 dark:text-red-400 transition disabled:opacity-30 disabled:hover:bg-red-50">
                <Lock size={13} />
              </button>
            )}
            <button onClick={() => onAction("reset", user.id)} title="Reset Limits" disabled={isDisabledAction}
              className="p-1.5 rounded-lg bg-blue-50 dark:bg-blue-950/30 hover:bg-blue-100 dark:hover:bg-blue-900/40 border border-blue-200 dark:border-blue-800/30 text-blue-700 dark:text-blue-400 transition disabled:opacity-30">
              <RefreshCw size={13} />
            </button>
            <button onClick={() => onAction("plan", user.id)} title="Change Plan" disabled={isDisabledAction}
              className="p-1.5 rounded-lg bg-yellow-50 dark:bg-yellow-950/30 hover:bg-yellow-100 dark:hover:bg-yellow-900/40 border border-yellow-200 dark:border-yellow-800/30 text-yellow-750 dark:text-yellow-400 transition disabled:opacity-30">
              <CrownIcon size={13} />
            </button>
            <button onClick={() => onAction("quota", user.id)} title="Custom Quota Override" disabled={isDisabledAction}
              className="p-1.5 rounded-lg bg-indigo-50 dark:bg-indigo-950/30 hover:bg-indigo-100 dark:hover:bg-indigo-900/40 border border-indigo-200 dark:border-indigo-800/30 text-indigo-700 dark:text-indigo-400 transition disabled:opacity-30">
              <Zap size={13} />
            </button>
            <button onClick={() => onAction("360", user.id)} title="Passenger 360° Profile & Gift Perks"
              className="p-1.5 rounded-lg bg-emerald-50 dark:bg-emerald-950/30 hover:bg-emerald-100 dark:hover:bg-emerald-900/40 border border-emerald-200 dark:border-emerald-800/30 text-emerald-600 dark:text-emerald-400 transition">
              <User size={13} />
            </button>
            <button onClick={() => setExpanded(v => !v)} title="Details"
              className="p-1.5 rounded-lg bg-input hover:bg-input/80 border border-subtle text-secondary transition">
              {expanded ? <ChevronUp size={13} /> : <ChevronDown size={13} />}
            </button>
          </div>
        </td>
      </tr>
      {expanded && (
        <tr className="bg-input/10 border-b border-subtle">
          <td colSpan={7} className="px-4 py-4">
            <div className="flex flex-col md:flex-row gap-6 justify-between items-start md:items-center">
              <div className="grid grid-cols-2 sm:grid-cols-4 gap-4 text-xs flex-1">
                <div><span className="text-muted font-semibold">Referral Code</span><br /><span className="text-main font-mono">{user.referralCode || "—"}</span></div>
                <div><span className="text-muted font-semibold">Credits</span><br /><span className="text-main font-mono">{user.credits ?? 0}</span></div>
                <div><span className="text-muted font-semibold">AI Split Searches</span><br /><span className="text-main font-mono">{user.aiSplitSearches ?? 0}</span></div>
                <div><span className="text-muted font-semibold">Plan Expiry</span><br /><span className="text-main font-mono">{user.planExpiry ? new Date(user.planExpiry).toLocaleDateString("en-IN") : "—"}</span></div>
              </div>
              
              <div className="flex flex-wrap items-center gap-3 border-t md:border-t-0 border-subtle pt-3 md:pt-0 w-full md:w-auto">
                <div className="flex items-center gap-2 bg-input border border-subtle rounded-lg p-1">
                  <input
                    type="number"
                    placeholder="+/- credits"
                    value={creditsChange}
                    onChange={e => setCreditsChange(e.target.value)}
                    disabled={isDisabledAction}
                    className="w-24 bg-transparent text-xs text-main font-medium px-2 py-1 focus:outline-none placeholder-muted disabled:opacity-40"
                  />
                  <button
                    onClick={handleAdjustCredits}
                    disabled={adjusting || !creditsChange || isDisabledAction}
                    className="px-2.5 py-1 bg-indigo-600 hover:bg-indigo-500 text-white rounded text-xs font-semibold transition disabled:opacity-45 disabled:hover:bg-indigo-600 flex items-center gap-1"
                  >
                    {adjusting ? <Loader2 size={10} className="animate-spin" /> : "Adjust"}
                  </button>
                </div>

                <button
                  onClick={handleTerminateSessions}
                  disabled={terminating || isDisabledAction}
                  className="px-3 py-1.5 bg-red-50 dark:bg-red-950/20 hover:bg-red-100 dark:hover:bg-red-900/30 border border-red-200 dark:border-red-800/30 text-red-655 dark:text-red-400 rounded-lg text-xs font-semibold transition flex items-center gap-1.5 disabled:opacity-30 disabled:hover:bg-red-50"
                >
                  <LogOut size={12} />
                  {terminating ? "Terminating..." : "Force Logout"}
                </button>
              </div>
            </div>
          </td>
        </tr>
      )}
    </>
  );
}

// ─── Users Directory Component ────────────────────────────────────────────────
export function UsersPanel({ api, getAuthHeaders, triggerToast }: {
  api: string;
  getAuthHeaders: () => Record<string, string>;
  triggerToast: (msg: string, type: "success" | "error" | "info") => void;
}) {
  const [users, setUsers] = useState<any[]>([]);
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState("");
  const [filterPlan, setFilterPlan] = useState("all");
  const [filterStatus, setFilterStatus] = useState("all");
  const [planModalUser, setPlanModalUser] = useState<any>(null);
  const [quotaModalUser, setQuotaModalUser] = useState<any>(null);
  const [selected360UserId, setSelected360UserId] = useState<string | null>(null);
  
  // Track logged in administrator's ID
  const [currentUserId, setCurrentUserId] = useState("");

  useEffect(() => {
    try {
      const user = JSON.parse(localStorage.getItem("user") || "{}");
      setCurrentUserId(user.id || "");
    } catch {
      setCurrentUserId("");
    }
  }, []);

  const fetchUsers = useCallback(async () => {
    setLoading(true);
    try {
      const res = await fetchWithAuth(`${api}/api/admin/users`, { headers: getAuthHeaders() });
      const json = await res.json();
      if (json.success) setUsers(json.data || []);
      else triggerToast("Failed to load users", "error");
    } catch { triggerToast("Network error loading users", "error"); }
    finally { setLoading(false); }
  }, [api, getAuthHeaders, triggerToast]);

  useEffect(() => { fetchUsers(); }, [fetchUsers]);

  const handleAction = async (type: string, userId: string, extra?: any) => {
    if (type === "360") {
      setSelected360UserId(userId);
      return;
    }
    if (type === "plan") {
      const user = users.find(u => u.id === userId);
      setPlanModalUser(user);
      return;
    }
    if (type === "quota") {
      const user = users.find(u => u.id === userId);
      setQuotaModalUser(user);
      return;
    }

    const endpoints: Record<string, string> = {
      block: `${api}/api/admin/users/${userId}/block`,
      unblock: `${api}/api/admin/users/${userId}/unblock`,
      reset: `${api}/api/admin/users/${userId}/reset-limits`,
      "terminate-sessions": `${api}/api/admin/users/${userId}/terminate-sessions`,
      "adjust-credits": `${api}/api/admin/users/${userId}/adjust-credits`,
    };

    const messages: Record<string, string> = {
      block: "Block this user? They will not be able to log in.",
      unblock: "Unblock this user?",
      reset: "Reset daily limits for this user?",
      "terminate-sessions": "Force logout user and terminate all active sessions?",
    };

    if (messages[type] && !window.confirm(messages[type])) return;

    let bodyData: any = undefined;
    if (type === "adjust-credits") {
      bodyData = JSON.stringify({ creditsChange: extra });
    }

    try {
      const res = await fetchWithAuth(endpoints[type], {
        method: "POST",
        headers: { "Content-Type": "application/json", ...getAuthHeaders() },
        body: bodyData
      });
      const json = await res.json();
      if (json.success) {
        triggerToast(json.message, "success");
        fetchUsers();
      } else {
        triggerToast(json.error || "Action failed", "error");
      }
    } catch { triggerToast("Network error", "error"); }
  };

  const handleToggleCheck = (userId: string) => {
    setSelectedIds(prev =>
      prev.includes(userId) ? prev.filter(id => id !== userId) : [...prev, userId]
    );
  };

  const handleToggleAll = () => {
    const selectableUsers = filtered.filter(u => !u.isAdmin && u.id !== currentUserId);
    if (selectedIds.length === selectableUsers.length) {
      setSelectedIds([]);
    } else {
      setSelectedIds(selectableUsers.map(u => u.id));
    }
  };

  const handleBulkAction = async (actionType: "bulk-block" | "bulk-unblock") => {
    // Frontend Cap validation: maximum 500 users per operation
    if (selectedIds.length > 500) {
      triggerToast("Bulk action capped at maximum 500 users per operation.", "error");
      return;
    }

    const actionLabel = actionType === "bulk-block" ? "BLOCK" : "UNBLOCK";
    const msg = `Are you sure you want to bulk ${actionLabel} ${selectedIds.length} selected users?`;
    if (!window.confirm(msg)) return;

    const endpoint = actionType === "bulk-block"
      ? `${api}/api/admin/users/bulk-block`
      : `${api}/api/admin/users/bulk-unblock`;

    try {
      const res = await fetchWithAuth(endpoint, {
        method: "POST",
        headers: { "Content-Type": "application/json", ...getAuthHeaders() },
        body: JSON.stringify({ targetIds: selectedIds, reason: "Bulk Admin Action" })
      });
      const json = await res.json();
      if (json.success) {
        triggerToast(json.message, "success");
        setSelectedIds([]);
        fetchUsers();
      } else {
        triggerToast(json.error || "Bulk action failed", "error");
      }
    } catch {
      triggerToast("Network error", "error");
    }
  };

  const filtered = users.filter(u => {
    const matchSearch = !search || u.email.toLowerCase().includes(search.toLowerCase()) || u.id.includes(search);
    const matchPlan = filterPlan === "all" || u.planType === filterPlan;
    const matchStatus = filterStatus === "all" || (filterStatus === "blocked" ? u.isBlocked : !u.isBlocked);
    return matchSearch && matchPlan && matchStatus;
  });

  const stats = {
    total: users.length,
    blocked: users.filter(u => u.isBlocked).length,
    premium: users.filter(u => u.planType !== "free" && u.planType !== "admin").length,
    admins: users.filter(u => u.isAdmin).length,
  };

  return (
    <div className="space-y-5">
      {/* Stats Row */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
        {[
          { label: "Total Users", value: stats.total, color: "text-blue-600 dark:text-blue-400", bg: "from-blue-500/10 dark:from-blue-900/20" },
          { label: "Premium", value: stats.premium, color: "text-yellow-750 dark:text-yellow-400", bg: "from-yellow-500/10 dark:from-yellow-900/20" },
          { label: "Blocked", value: stats.blocked, color: "text-red-655 dark:text-red-400", bg: "from-red-500/10 dark:from-red-900/20" },
          { label: "Admins", value: stats.admins, color: "text-purple-600 dark:text-purple-400", bg: "from-purple-500/10 dark:from-purple-900/20" },
        ].map(s => (
          <div key={s.label} className={`bg-gradient-to-br ${s.bg} to-transparent border border-subtle rounded-xl p-4`}>
            <div className={`text-2xl font-bold ${s.color}`}>{s.value}</div>
            <div className="text-xs text-muted mt-1">{s.label}</div>
          </div>
        ))}
      </div>

      {/* Filters */}
      <div className="flex flex-col sm:flex-row gap-3">
        <div className="relative flex-1">
          <Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-muted" />
          <input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search by email or ID…"
            className="w-full pl-9 pr-4 py-2 bg-input border border-subtle rounded-lg text-sm text-main focus:outline-none focus:border-strong transition" />
        </div>
        <select value={filterPlan} onChange={e => setFilterPlan(e.target.value)}
          className="px-3 py-2 bg-input border border-subtle rounded-lg text-sm text-main focus:outline-none focus:border-strong">
          <option value="all" className="bg-card text-main">All Plans</option>
          <option value="free" className="bg-card text-main">Free</option>
          <option value="safar_pro_30d" className="bg-card text-main">Blitz Pro</option>
          <option value="paid" className="bg-card text-main">Legacy Paid</option>
          <option value="admin" className="bg-card text-main">Admin</option>
        </select>
        <select value={filterStatus} onChange={e => setFilterStatus(e.target.value)}
          className="px-3 py-2 bg-input border border-subtle rounded-lg text-sm text-main focus:outline-none focus:border-strong">
          <option value="all" className="bg-card text-main">All Status</option>
          <option value="active" className="bg-card text-main">Active</option>
          <option value="blocked" className="bg-card text-main">Blocked</option>
        </select>
        <button onClick={fetchUsers} disabled={loading} className="px-3 py-2 bg-input hover:bg-input/80 border border-subtle rounded-lg text-secondary transition" title="Refresh">
          <RefreshCw size={14} />
        </button>
      </div>

      {/* Table */}
      <div className="bg-card border border-subtle rounded-xl overflow-hidden animate-fade-in">
        {loading ? (
          <div className="flex items-center justify-center py-16 gap-3 text-muted">
            <Loader2 size={20} className="animate-spin" /> Loading users…
          </div>
        ) : filtered.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-16 gap-3 text-muted">
            <UserX size={36} />
            <p className="text-sm">No users match your filters</p>
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead>
                <tr className="border-b border-subtle text-xs text-secondary uppercase tracking-wider text-left bg-input/40">
                  <th className="px-4 py-3 text-left w-10">
                    <input
                      type="checkbox"
                      checked={filtered.length > 0 && selectedIds.length === filtered.filter(u => !u.isAdmin && u.id !== currentUserId).length}
                      onChange={handleToggleAll}
                      className="rounded border-subtle bg-input text-indigo-600 focus:ring-indigo-500/50 w-4 h-4 cursor-pointer"
                    />
                  </th>
                  <th className="px-4 py-3">User</th>
                  <th className="px-4 py-3">Plan</th>
                  <th className="px-4 py-3">Joined</th>
                  <th className="px-4 py-3">Usage Today</th>
                  <th className="px-4 py-3">Status</th>
                  <th className="px-4 py-3">Actions</th>
                </tr>
              </thead>
              <tbody>
                {filtered.map(u => (
                  <UserRow
                    key={u.id}
                    user={u}
                    currentUserId={currentUserId}
                    checked={selectedIds.includes(u.id)}
                    onToggleCheck={handleToggleCheck}
                    onAction={handleAction}
                  />
                ))}
              </tbody>
            </table>
          </div>
        )}
        {!loading && (
          <div className="px-4 py-3 border-t border-subtle text-xs text-muted">
            Showing {filtered.length} of {users.length} users
          </div>
        )}
      </div>

      {/* Bulk Actions Drawer */}
      {selectedIds.length > 0 && (
        <div className="fixed bottom-6 left-1/2 -translate-x-1/2 z-40 flex items-center gap-4 bg-card/90 dark:bg-zinc-950/90 border border-subtle rounded-2xl px-6 py-4 shadow-2xl backdrop-blur-md animate-slide-up w-[90%] max-w-2xl justify-between">
          <div className="flex items-center gap-3">
            <span className="flex h-6 w-6 items-center justify-center rounded-full bg-indigo-100 dark:bg-indigo-900 text-xs font-bold text-indigo-705 dark:text-indigo-300 border border-indigo-200 dark:border-indigo-805">
              {selectedIds.length}
            </span>
            <span className="text-sm font-medium text-main font-semibold">users selected</span>
          </div>

          <div className="flex items-center gap-3">
            <button
              onClick={() => handleBulkAction("bulk-block")}
              className="px-4 py-2 bg-red-50 dark:bg-red-950/20 hover:bg-red-100 dark:hover:bg-red-900/40 border border-red-200 dark:border-red-800/30 text-red-655 dark:text-red-400 rounded-xl text-xs font-semibold transition flex items-center gap-1.5"
            >
              <Lock size={12} /> Bulk Block
            </button>
            <button
              onClick={() => handleBulkAction("bulk-unblock")}
              className="px-4 py-2 bg-emerald-50 dark:bg-emerald-950/20 hover:bg-emerald-100 dark:hover:bg-emerald-900/30 border border-emerald-200 dark:border-emerald-800/30 text-emerald-700 dark:text-emerald-400 rounded-xl text-xs font-semibold transition flex items-center gap-1.5"
            >
              <Unlock size={12} /> Bulk Unblock
            </button>
            <button
              onClick={() => setSelectedIds([])}
              className="p-2 bg-input hover:bg-input/80 border border-subtle text-secondary rounded-xl transition"
              title="Clear selection"
            >
              <X size={14} />
            </button>
          </div>
        </div>
      )}

      {/* Plan Modal */}
      {planModalUser && (
        <PlanModal
          userId={planModalUser.id}
          currentPlan={planModalUser.planType}
          api={api}
          getAuthHeaders={getAuthHeaders}
          onClose={() => setPlanModalUser(null)}
          onSuccess={msg => { triggerToast(msg, "success"); fetchUsers(); }}
        />
      )}

      {/* Quota Override Modal */}
      {quotaModalUser && (
        <QuotaModal
          userId={quotaModalUser.id}
          currentSearches={quotaModalUser.dailySearchCount || 5}
          currentPnr={quotaModalUser.dailyPnrCount || 3}
          currentLive={quotaModalUser.dailyLiveCount || 3}
          api={api}
          getAuthHeaders={getAuthHeaders}
          onClose={() => setQuotaModalUser(null)}
          onSuccess={msg => { triggerToast(msg, "success"); fetchUsers(); }}
        />
      )}

      {/* Passenger 360° Profile Drawer & Perks Modal */}
      {selected360UserId && (
        <User360Drawer
          userId={selected360UserId}
          api={api}
          getAuthHeaders={getAuthHeaders}
          onClose={() => setSelected360UserId(null)}
          triggerToast={triggerToast}
          onRefreshUsers={fetchUsers}
        />
      )}
    </div>
  );
}
