"use client";

import React, { useEffect, useState, useCallback } from "react";
import {
  Megaphone, Smartphone, Mail, Send, Radio, CheckCircle2,
  AlertCircle, RefreshCw, Sparkles, Tag, ExternalLink, Flame,
  Users, Eye, Check, X, ShieldCheck, Zap, ArrowRight, MessageSquare
} from "lucide-react";
import { fetchWithAuth } from "@/lib/fetchWithAuth";

interface BroadcastCenterPanelProps {
  api: string;
  getAuthHeaders: () => Record<string, string>;
  triggerToast: (msg: string, type: "success" | "error" | "info") => void;
}

type ChannelType = "BOTH" | "WHATSAPP" | "EMAIL";

export function BroadcastCenterPanel({ api, getAuthHeaders, triggerToast }: BroadcastCenterPanelProps) {
  // Audience stats
  const [audienceLoading, setAudienceLoading] = useState<boolean>(true);
  const [audienceStats, setAudienceStats] = useState({
    totalUsers: 543,
    emailUsers: 543,
    phoneUsers: 180,
    verifiedPhoneUsers: 28
  });

  // Channel & Composer state
  const [channel, setChannel] = useState<ChannelType>("BOTH");
  const [title, setTitle] = useState<string>("Diwali Special Offer: Get Trayago Pro for just ₹35!");
  const [message, setMessage] = useState<string>(
    `Festive season planning is in full swing, and we know how stressful it can be when direct train tickets show long waitlists.\n\nThis Diwali, we want to make sure you reach your destination smoothly. That is why we are giving you full access to Trayago Pro for just ₹35 (originally ₹49) for the next 30 days!\n\n🪔 Here is what you unlock with Trayago Pro:\n• Unlimited AI Hidden Split Journeys: Connect legs to find confirmed seats when direct is full.\n• Live Train GPS Alerts & Speedometer: Real-time station tracking, platform indicator & delay alerts.\n• Smart PNR Confirmation Probabilities: 92%+ accurate confirmation forecast.\n• High Priority Support & Dedicated Server Auto-Refresh.\n\nDon't let a waitlisted ticket keep you away from family celebrations this festive season. Upgrade today and travel smarter.`
  );
  const [offerPrice, setOfferPrice] = useState<string>("₹35");
  const [originalPrice, setOriginalPrice] = useState<string>("₹49");
  const [promoCode, setPromoCode] = useState<string>("OFFER35");
  const [actionLabel, setActionLabel] = useState<string>("Claim 1 Month Pro for ₹35");
  const [actionUrl, setActionUrl] = useState<string>("https://www.trayago.in/pricing?code=OFFER35");
  const [bannerUrl, setBannerUrl] = useState<string>("https://www.trayago.in/branding/trayago-diwali-2026.jpg");

  // Preview tab: email or whatsapp
  const [previewTab, setPreviewTab] = useState<"email" | "whatsapp">("email");

  // Test & Broadcast states
  const [testEmail, setTestEmail] = useState<string>("peershaikh25@gmail.com");
  const [testPhone, setTestPhone] = useState<string>("+919876543210");
  const [isTestSending, setIsTestSending] = useState<boolean>(false);
  const [isBroadcasting, setIsBroadcasting] = useState<boolean>(false);
  const [broadcastResult, setBroadcastResult] = useState<any>(null);

  // Fetch live audience numbers
  const fetchAudienceStats = useCallback(async () => {
    try {
      setAudienceLoading(true);
      const res = await fetchWithAuth(`${api}/api/admin/broadcast/audience-stats`, {
        headers: getAuthHeaders()
      });
      if (res.ok) {
        const json = await res.json();
        if (json.success && json.data) {
          setAudienceStats(json.data);
        }
      }
    } catch (err: any) {
      console.error("[AUDIENCE_STATS_FETCH_ERR]", err);
    } finally {
      setAudienceLoading(false);
    }
  }, [api, getAuthHeaders]);

  useEffect(() => {
    fetchAudienceStats();
  }, [fetchAudienceStats]);

  // Template Presets
  const applyPreset = (presetName: string) => {
    if (presetName === "diwali") {
      setTitle("Diwali Special Offer: Get Trayago Pro for just ₹35!");
      setMessage(
        `Festive season planning is in full swing, and we know how stressful it can be when direct train tickets show long waitlists.\n\nThis Diwali, we want to make sure you reach your destination smoothly. That is why we are giving you full access to Trayago Pro for just ₹35 (originally ₹49) for the next 30 days!\n\n🪔 Here is what you unlock with Trayago Pro:\n• Unlimited AI Hidden Split Journeys: Connect legs to find confirmed seats when direct is full.\n• Live Train GPS Alerts & Speedometer: Real-time station tracking, platform indicator & delay alerts.\n• Smart PNR Confirmation Probabilities: 92%+ accurate confirmation forecast.\n• High Priority Support & Dedicated Server Auto-Refresh.\n\nDon't let a waitlisted ticket keep you away from family celebrations this festive season. Upgrade today and travel smarter.`
      );
      setOfferPrice("₹35");
      setOriginalPrice("₹49");
      setPromoCode("OFFER35");
      setActionLabel("Claim 1 Month Pro for ₹35");
      setActionUrl("https://www.trayago.in/pricing?code=OFFER35");
      setBannerUrl("https://www.trayago.in/branding/trayago-diwali-2026.jpg");
      triggerToast("Diwali ₹35 Special template loaded!", "info");
    } else if (presetName === "weekend_pass") {
      setTitle("⚡ Weekend Travel Flash: 24h AI Pass for just ₹19!");
      setMessage(
        `Travelling this weekend? Skip ticket waitlist stress with the 24-Hour Trayago AI Pass.\n\nDiscover hidden confirmed seats across connecting stations in seconds, track your live train GPS location, and stay ahead of platform changes.`
      );
      setOfferPrice("₹19");
      setOriginalPrice("₹49");
      setPromoCode("PASS19");
      setActionLabel("Unlock 24h Pass for ₹19");
      setActionUrl("https://www.trayago.in/pricing?plan=safar_pro_1d&code=PASS19");
      setBannerUrl("");
      triggerToast("Weekend 24h Pass template loaded!", "info");
    } else if (presetName === "speedometer_feature") {
      setTitle("🛰️ New Feature Live: In-Train GPS Speedometer & Stop HUD");
      setMessage(
        `Now you can monitor your train speed in real time right from inside the coach!\n\nOpen Trayago Live Tracker, toggle 'Inside Train (GPS)', and see a high-contrast speedometer radial gauge (0-160 km/h), upcoming platform alerts, and offline station tracking.`
      );
      setOfferPrice("");
      setOriginalPrice("");
      setPromoCode("");
      setActionLabel("Open Live Speedometer");
      setActionUrl("https://www.trayago.in/live?mode=inside");
      setBannerUrl("");
      triggerToast("GPS Speedometer feature alert loaded!", "info");
    } else if (presetName === "blank") {
      setTitle("");
      setMessage("");
      setOfferPrice("");
      setOriginalPrice("");
      setPromoCode("");
      setActionLabel("Visit Trayago");
      setActionUrl("https://www.trayago.in");
      setBannerUrl("");
      triggerToast("Cleared composer for blank campaign.", "info");
    }
  };

  // Test Dispatch
  const handleTestDispatch = async () => {
    if (!title.trim() || !message.trim()) {
      triggerToast("Title and message body are required.", "error");
      return;
    }

    try {
      setIsTestSending(true);
      const res = await fetchWithAuth(`${api}/api/admin/broadcast/dispatch`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          ...getAuthHeaders()
        },
        body: JSON.stringify({
          channel,
          mode: "test",
          testEmail: (channel === "EMAIL" || channel === "BOTH") ? testEmail : undefined,
          testPhone: (channel === "WHATSAPP" || channel === "BOTH") ? testPhone : undefined,
          title,
          message,
          offerPrice: offerPrice || undefined,
          originalPrice: originalPrice || undefined,
          promoCode: promoCode || undefined,
          actionUrl,
          actionLabel,
          bannerUrl: bannerUrl || undefined
        })
      });

      const json = await res.json();
      if (json.success) {
        triggerToast("Test message sent! Check your WhatsApp and/or Email inbox.", "success");
      } else {
        triggerToast(json.error || "Failed to dispatch test message.", "error");
      }
    } catch (err: any) {
      triggerToast(`Network error: ${err.message}`, "error");
    } finally {
      setIsTestSending(false);
    }
  };

  // Mass Broadcast
  const handleBroadcast = async () => {
    if (!title.trim() || !message.trim()) {
      triggerToast("Title and message body are required.", "error");
      return;
    }

    const targetDesc = channel === "BOTH"
      ? `all 543 Email users AND 180 registered WhatsApp numbers`
      : channel === "EMAIL"
        ? `all 543 registered Email users`
        : `all 180 registered WhatsApp numbers`;

    const confirmMsg = `Are you sure you want to broadcast this campaign to ${targetDesc}?\n\nTitle: "${title}"\nChannel: ${channel}`;
    if (!window.confirm(confirmMsg)) return;

    try {
      setIsBroadcasting(true);
      setBroadcastResult(null);

      const res = await fetchWithAuth(`${api}/api/admin/broadcast/dispatch`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          ...getAuthHeaders()
        },
        body: JSON.stringify({
          channel,
          mode: "broadcast",
          title,
          message,
          offerPrice: offerPrice || undefined,
          originalPrice: originalPrice || undefined,
          promoCode: promoCode || undefined,
          actionUrl,
          actionLabel,
          bannerUrl: bannerUrl || undefined
        })
      });

      const json = await res.json();
      if (json.success) {
        setBroadcastResult(json);
        triggerToast(`Broadcast completed! Delivered: ${json.totalDelivered}`, "success");
      } else {
        triggerToast(json.error || "Broadcast failed", "error");
      }
    } catch (err: any) {
      triggerToast(`Broadcast error: ${err.message}`, "error");
    } finally {
      setIsBroadcasting(false);
    }
  };

  // Target audience count based on channel
  const currentTargetCount = channel === "BOTH"
    ? `${audienceStats.emailUsers} Emails + ${audienceStats.phoneUsers} WhatsApp`
    : channel === "EMAIL"
      ? `${audienceStats.emailUsers} Emails`
      : `${audienceStats.phoneUsers} WhatsApp Numbers`;

  return (
    <div className="space-y-6 animate-fade-in">
      {/* Top Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 border-b border-subtle pb-4">
        <div>
          <h2 className="text-xl font-bold flex items-center gap-2 text-main">
            <Megaphone className="text-amber-400" size={22} />
            Omnichannel Broadcast Center
          </h2>
          <p className="text-xs text-muted mt-1">
            Send custom promotional offers, hyperlinks, and pricing campaigns directly to all registered WhatsApp numbers and Email users.
          </p>
        </div>

        <button
          type="button"
          onClick={fetchAudienceStats}
          disabled={audienceLoading}
          className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg bg-input hover:bg-card border border-subtle text-xs font-semibold text-muted hover:text-main transition"
        >
          <RefreshCw size={12} className={audienceLoading ? "animate-spin" : ""} />
          <span>Sync Audience Count</span>
        </button>
      </div>

      {/* Live Audience Metrics Cards */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-3 sm:gap-4">
        <div className="p-4 rounded-2xl bg-card border border-subtle space-y-1">
          <div className="flex items-center justify-between text-muted text-xs">
            <span>Total Registered</span>
            <Users size={14} className="text-primary" />
          </div>
          <div className="text-2xl font-black text-main font-mono">{audienceStats.totalUsers}</div>
          <p className="text-[10px] text-muted">Active database members</p>
        </div>

        <div className="p-4 rounded-2xl bg-card border border-subtle space-y-1">
          <div className="flex items-center justify-between text-muted text-xs">
            <span>Email Contacts</span>
            <Mail size={14} className="text-blue-400" />
          </div>
          <div className="text-2xl font-black text-blue-400 font-mono">{audienceStats.emailUsers}</div>
          <p className="text-[10px] text-muted">100% verified inbox delivery</p>
        </div>

        <div className="p-4 rounded-2xl bg-card border border-subtle space-y-1">
          <div className="flex items-center justify-between text-muted text-xs">
            <span>WhatsApp Numbers</span>
            <Smartphone size={14} className="text-emerald-400" />
          </div>
          <div className="text-2xl font-black text-emerald-400 font-mono">{audienceStats.phoneUsers}</div>
          <p className="text-[10px] text-muted">Registered mobile users</p>
        </div>

        <div className="p-4 rounded-2xl bg-card border border-subtle space-y-1">
          <div className="flex items-center justify-between text-muted text-xs">
            <span>WhatsApp Verified</span>
            <ShieldCheck size={14} className="text-purple-400" />
          </div>
          <div className="text-2xl font-black text-purple-400 font-mono">{audienceStats.verifiedPhoneUsers}</div>
          <p className="text-[10px] text-muted">OTP authenticated numbers</p>
        </div>
      </div>

      {/* Channel Selector Pills */}
      <div className="p-4 rounded-2xl bg-card border border-subtle space-y-3">
        <label className="text-xs font-bold text-muted uppercase tracking-wider block">
          Select Broadcast Channel
        </label>
        <div className="grid grid-cols-1 sm:grid-cols-3 gap-2">
          <button
            type="button"
            onClick={() => setChannel("BOTH")}
            className={`p-3 rounded-xl border text-xs font-bold transition flex items-center justify-center gap-2 ${
              channel === "BOTH"
                ? "bg-gradient-to-r from-amber-500/20 via-orange-500/20 to-primary/20 border-amber-500/50 text-amber-400 shadow-md"
                : "bg-input border-subtle text-muted hover:text-main"
            }`}
          >
            <Zap size={14} className={channel === "BOTH" ? "text-amber-400" : ""} />
            <span>Dual: WhatsApp + Email</span>
          </button>

          <button
            type="button"
            onClick={() => setChannel("WHATSAPP")}
            className={`p-3 rounded-xl border text-xs font-bold transition flex items-center justify-center gap-2 ${
              channel === "WHATSAPP"
                ? "bg-emerald-500/15 border-emerald-500/50 text-emerald-400 shadow-md"
                : "bg-input border-subtle text-muted hover:text-main"
            }`}
          >
            <Smartphone size={14} className={channel === "WHATSAPP" ? "text-emerald-400" : ""} />
            <span>WhatsApp Only ({audienceStats.phoneUsers})</span>
          </button>

          <button
            type="button"
            onClick={() => setChannel("EMAIL")}
            className={`p-3 rounded-xl border text-xs font-bold transition flex items-center justify-center gap-2 ${
              channel === "EMAIL"
                ? "bg-blue-500/15 border-blue-500/50 text-blue-400 shadow-md"
                : "bg-input border-subtle text-muted hover:text-main"
            }`}
          >
            <Mail size={14} className={channel === "EMAIL" ? "text-blue-400" : ""} />
            <span>Email Only ({audienceStats.emailUsers})</span>
          </button>
        </div>
      </div>

      {/* Template Quick Presets Bar */}
      <div className="flex flex-wrap items-center gap-2 pt-1">
        <span className="text-xs font-bold text-muted flex items-center gap-1 mr-1">
          <Sparkles size={13} className="text-amber-400" /> Quick Presets:
        </span>
        <button
          type="button"
          onClick={() => applyPreset("diwali")}
          className="px-3 py-1.5 rounded-lg bg-amber-500/15 hover:bg-amber-500/25 border border-amber-500/30 text-amber-300 text-xs font-bold transition flex items-center gap-1.5"
        >
          <span>🪔 Diwali Special (₹35)</span>
        </button>
        <button
          type="button"
          onClick={() => applyPreset("weekend_pass")}
          className="px-3 py-1.5 rounded-lg bg-blue-500/15 hover:bg-blue-500/25 border border-blue-500/30 text-blue-300 text-xs font-bold transition flex items-center gap-1.5"
        >
          <span>⚡ 24h AI Pass (₹19)</span>
        </button>
        <button
          type="button"
          onClick={() => applyPreset("speedometer_feature")}
          className="px-3 py-1.5 rounded-lg bg-purple-500/15 hover:bg-purple-500/25 border border-purple-500/30 text-purple-300 text-xs font-bold transition flex items-center gap-1.5"
        >
          <span>🛰️ GPS Speedometer Feature</span>
        </button>
        <button
          type="button"
          onClick={() => applyPreset("blank")}
          className="px-3 py-1.5 rounded-lg bg-input hover:bg-card border border-subtle text-muted hover:text-main text-xs font-semibold transition"
        >
          <span>Clear All</span>
        </button>
      </div>

      {/* Main Grid: Composer on Left, Live Mockup on Right */}
      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
        {/* Left Column: Campaign Composer (7 cols) */}
        <div className="lg:col-span-7 space-y-4">
          {/* Campaign Title */}
          <div className="space-y-1">
            <label className="text-xs font-bold text-muted uppercase tracking-wider">
              Campaign Title / Email Subject
            </label>
            <input
              type="text"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              placeholder="e.g. Diwali Mahotsav: Get Trayago Pro for ₹35!"
              className="w-full bg-input border border-subtle rounded-xl px-3 py-2.5 text-xs text-main font-bold focus:outline-none focus:border-strong transition"
            />
          </div>

          {/* Message Body */}
          <div className="space-y-1">
            <div className="flex items-center justify-between">
              <label className="text-xs font-bold text-muted uppercase tracking-wider">
                Message Content Body
              </label>
              <span className="text-[10px] text-muted">Supports multiple paragraphs &amp; emojis</span>
            </div>
            <textarea
              rows={7}
              value={message}
              onChange={(e) => setMessage(e.target.value)}
              placeholder="Write your custom promotional message here..."
              className="w-full bg-input border border-subtle rounded-xl px-3 py-2.5 text-xs text-main font-normal focus:outline-none focus:border-strong transition resize-y font-sans leading-relaxed"
            />
          </div>

          {/* Pricing & Offer Options Card */}
          <div className="p-4 rounded-2xl bg-card border border-subtle space-y-3">
            <div className="flex items-center justify-between">
              <span className="text-xs font-bold text-main flex items-center gap-1.5">
                <Tag size={13} className="text-amber-400" /> Special Offer &amp; Pricing (Optional)
              </span>
              <span className="text-[10px] text-muted">Included inside email badge and WhatsApp highlight</span>
            </div>

            <div className="grid grid-cols-3 gap-3">
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-muted uppercase">Offer Price</label>
                <input
                  type="text"
                  value={offerPrice}
                  onChange={(e) => setOfferPrice(e.target.value)}
                  placeholder="e.g. ₹35"
                  className="w-full bg-input border border-subtle rounded-xl px-3 py-2 text-xs text-emerald-400 font-mono font-bold focus:outline-none focus:border-strong transition"
                />
              </div>

              <div className="space-y-1">
                <label className="text-[10px] font-bold text-muted uppercase">Original Price</label>
                <input
                  type="text"
                  value={originalPrice}
                  onChange={(e) => setOriginalPrice(e.target.value)}
                  placeholder="e.g. ₹49"
                  className="w-full bg-input border border-subtle rounded-xl px-3 py-2 text-xs text-muted font-mono line-through focus:outline-none focus:border-strong transition"
                />
              </div>

              <div className="space-y-1">
                <label className="text-[10px] font-bold text-muted uppercase">Promo Code</label>
                <input
                  type="text"
                  value={promoCode}
                  onChange={(e) => setPromoCode(e.target.value.toUpperCase())}
                  placeholder="e.g. OFFER35"
                  className="w-full bg-input border border-subtle rounded-xl px-3 py-2 text-xs text-amber-400 font-mono font-bold focus:outline-none focus:border-strong transition"
                />
              </div>
            </div>
          </div>

          {/* Hyperlink & CTA Button */}
          <div className="p-4 rounded-2xl bg-card border border-subtle space-y-3">
            <span className="text-xs font-bold text-main flex items-center gap-1.5">
              <ExternalLink size={13} className="text-primary" /> Action Button &amp; Hyperlink
            </span>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-muted uppercase">Button Label</label>
                <input
                  type="text"
                  value={actionLabel}
                  onChange={(e) => setActionLabel(e.target.value)}
                  placeholder="e.g. Claim 1 Month Pro for ₹35"
                  className="w-full bg-input border border-subtle rounded-xl px-3 py-2 text-xs text-main font-bold focus:outline-none focus:border-strong transition"
                />
              </div>

              <div className="space-y-1">
                <label className="text-[10px] font-bold text-muted uppercase">Target URL (Hyperlink)</label>
                <input
                  type="text"
                  value={actionUrl}
                  onChange={(e) => setActionUrl(e.target.value)}
                  placeholder="https://www.trayago.in/pricing?code=OFFER35"
                  className="w-full bg-input border border-subtle rounded-xl px-3 py-2 text-xs text-blue-400 font-mono focus:outline-none focus:border-strong transition"
                />
              </div>
            </div>
          </div>

          {/* Banner Image URL (Optional) */}
          <div className="space-y-1">
            <label className="text-xs font-bold text-muted uppercase tracking-wider">
              Hero Banner Image URL (Optional for Email)
            </label>
            <input
              type="text"
              value={bannerUrl}
              onChange={(e) => setBannerUrl(e.target.value)}
              placeholder="https://www.trayago.in/branding/trayago-diwali-2026.jpg"
              className="w-full bg-input border border-subtle rounded-xl px-3 py-2 text-xs text-secondary font-mono focus:outline-none focus:border-strong transition"
            />
          </div>
        </div>

        {/* Right Column: Live Mockup Preview (5 cols) */}
        <div className="lg:col-span-5 space-y-3">
          <div className="flex items-center justify-between">
            <span className="text-xs font-bold text-muted uppercase tracking-wider flex items-center gap-1.5">
              <Eye size={13} className="text-primary" /> Live Channel Preview
            </span>
            <div className="flex gap-1 bg-input p-0.5 rounded-lg border border-subtle">
              <button
                type="button"
                onClick={() => setPreviewTab("email")}
                className={`px-2.5 py-1 rounded text-[11px] font-bold transition ${
                  previewTab === "email" ? "bg-card text-main shadow-sm" : "text-muted hover:text-main"
                }`}
              >
                ✉️ Email
              </button>
              <button
                type="button"
                onClick={() => setPreviewTab("whatsapp")}
                className={`px-2.5 py-1 rounded text-[11px] font-bold transition ${
                  previewTab === "whatsapp" ? "bg-card text-main shadow-sm" : "text-muted hover:text-main"
                }`}
              >
                📱 WhatsApp
              </button>
            </div>
          </div>

          {/* PREVIEW CONTAINER */}
          {previewTab === "email" ? (
            /* Email Mockup */
            <div className="rounded-2xl border border-subtle bg-slate-900 p-4 shadow-xl text-slate-100 overflow-hidden font-sans space-y-3">
              {/* Email Top Bar */}
              <div className="flex items-center justify-between pb-2 border-b border-slate-800 text-[11px]">
                <div className="flex items-center gap-2">
                  <div className="w-5 h-5 rounded bg-blue-600 flex items-center justify-center text-white text-[10px] font-black">T</div>
                  <span className="font-bold text-white">Trayago Official Update</span>
                </div>
                <span className="text-slate-400 font-mono text-[10px]">Inbox Preview</span>
              </div>

              {/* Banner Image */}
              {bannerUrl && (
                <div className="rounded-xl overflow-hidden border border-slate-800 bg-slate-950">
                  <img src={bannerUrl} alt="Campaign Banner" className="w-full h-auto object-cover max-h-40" />
                </div>
              )}

              {/* Content Body */}
              <div className="bg-white text-slate-900 rounded-xl p-4 space-y-3 shadow">
                <div className="text-xs font-bold text-slate-900">
                  Namaste Traveler,
                </div>
                <h4 className="text-sm font-black text-slate-950 leading-tight">
                  {title || "Campaign Title Preview"}
                </h4>
                <div className="text-[11px] text-slate-600 space-y-1.5 leading-relaxed whitespace-pre-wrap line-clamp-6">
                  {message}
                </div>

                {/* Offer Price Highlight Box */}
                {offerPrice && (
                  <div className="p-3 rounded-xl bg-amber-50 border border-amber-300 text-center space-y-1.5">
                    <span className="px-2 py-0.5 rounded-full bg-amber-600 text-white text-[9px] font-bold uppercase">
                      Special Offer
                    </span>
                    <div className="flex items-baseline justify-center gap-2">
                      <span className="text-xl font-black text-amber-700 font-mono">{offerPrice}</span>
                      {originalPrice && <span className="text-xs text-slate-400 line-through font-mono">{originalPrice}</span>}
                    </div>
                    {promoCode && (
                      <div className="text-[10px] font-mono font-bold text-amber-800 bg-white border border-amber-200 px-2 py-0.5 rounded inline-block">
                        CODE: {promoCode}
                      </div>
                    )}
                  </div>
                )}

                {/* CTA Button */}
                <div className="text-center pt-1">
                  <a
                    href={actionUrl}
                    target="_blank"
                    rel="noreferrer"
                    className="inline-block w-full py-2.5 rounded-xl bg-slate-950 text-white text-xs font-black text-center shadow hover:opacity-90 transition"
                  >
                    {actionLabel} &rarr;
                  </a>
                </div>
              </div>
            </div>
          ) : (
            /* WhatsApp Mockup */
            <div className="rounded-2xl border border-emerald-900/40 bg-[#0c1317] p-4 shadow-xl text-slate-100 font-sans space-y-3">
              {/* WhatsApp Header */}
              <div className="flex items-center gap-2.5 pb-2 border-b border-slate-800">
                <div className="w-8 h-8 rounded-full bg-emerald-600 flex items-center justify-center text-white font-bold text-xs">
                  T
                </div>
                <div className="flex-1 min-w-0">
                  <div className="text-xs font-bold text-white flex items-center gap-1 truncate">
                    <span>Trayago Verified</span>
                    <CheckCircle2 size={12} className="text-emerald-400 shrink-0" />
                  </div>
                  <div className="text-[10px] text-emerald-400">Official Business Account</div>
                </div>
              </div>

              {/* Chat Bubble */}
              <div className="bg-[#1f2c34] rounded-2xl rounded-tl-none p-3.5 space-y-2 text-xs text-slate-200 border border-emerald-950 shadow">
                <div className="font-bold text-emerald-400">
                  *{title || "Special Announcement"}*
                </div>
                <div className="text-[11px] text-slate-300 leading-relaxed whitespace-pre-wrap">
                  {message}
                </div>

                {offerPrice && (
                  <div className="pt-1 text-[11px] text-amber-300 font-semibold border-t border-slate-700/60">
                    🎉 *Special Offer: {offerPrice}* {originalPrice && `(~${originalPrice}~)`}
                    {promoCode && <div className="text-slate-300 mt-0.5">🎟️ Promo Code: *{promoCode}*</div>}
                  </div>
                )}

                {actionUrl && (
                  <div className="pt-1 text-[11px] text-blue-400 underline break-all">
                    👉 *{actionLabel}:* {actionUrl}
                  </div>
                )}

                <div className="flex justify-end text-[9px] text-slate-400 pt-1">
                  <span>12:00 PM</span>
                  <span className="text-blue-400 ml-1">✓✓</span>
                </div>
              </div>
            </div>
          )}

          <div className="text-[11px] text-muted text-center">
            Target Audience for this Broadcast: <strong className="text-main">{currentTargetCount}</strong>
          </div>
        </div>
      </div>

      {/* Execution Controls Bottom Bar */}
      <div className="rounded-3xl border border-subtle bg-card p-5 space-y-4 shadow-xl">
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
          <div className="flex items-center gap-2">
            <span className="w-6 h-6 rounded-full bg-primary/20 text-primary text-xs font-black flex items-center justify-center">
              🚀
            </span>
            <span className="text-xs font-bold text-main uppercase tracking-wider">
              Launch Dispatch Center
            </span>
          </div>

          <div className="text-xs text-muted">
            Safe batch rate: <strong className="text-main">15 messages/second</strong> with failover protection.
          </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-4">
          {/* Test Box */}
          <div className="lg:col-span-6 p-4 rounded-2xl bg-input/40 border border-subtle space-y-3">
            <div className="text-xs font-bold text-main flex items-center gap-1.5">
              <span>Step 1: Send Test Dispatch (Verify First)</span>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
              {(channel === "EMAIL" || channel === "BOTH") && (
                <input
                  type="email"
                  value={testEmail}
                  onChange={(e) => setTestEmail(e.target.value)}
                  placeholder="test-email@gmail.com"
                  className="w-full bg-input border border-subtle rounded-xl px-3 py-2 text-xs text-main font-semibold focus:outline-none focus:border-strong transition"
                />
              )}
              {(channel === "WHATSAPP" || channel === "BOTH") && (
                <input
                  type="tel"
                  value={testPhone}
                  onChange={(e) => setTestPhone(e.target.value)}
                  placeholder="+919876543210"
                  className="w-full bg-input border border-subtle rounded-xl px-3 py-2 text-xs text-main font-semibold focus:outline-none focus:border-strong transition"
                />
              )}
            </div>

            <button
              type="button"
              onClick={handleTestDispatch}
              disabled={isTestSending}
              className="w-full py-2.5 bg-card hover:bg-input border border-subtle text-main font-bold text-xs rounded-xl transition flex items-center justify-center gap-2 disabled:opacity-50"
            >
              {isTestSending ? <RefreshCw size={13} className="animate-spin" /> : <Send size={13} />}
              <span>{isTestSending ? "Sending Test..." : "Send Test to My Device"}</span>
            </button>
          </div>

          {/* Mass Broadcast Box */}
          <div className="lg:col-span-6 p-4 rounded-2xl bg-gradient-to-br from-amber-500/10 via-card to-card border border-amber-500/30 flex flex-col justify-between space-y-3">
            <div className="space-y-1">
              <div className="text-xs font-bold text-amber-400 flex items-center gap-1.5">
                <Flame size={14} /> Step 2: Mass Broadcast to All Registered Users
              </div>
              <p className="text-[11px] text-muted">
                Will dispatch simultaneously to <strong className="text-main font-bold">{currentTargetCount}</strong> in safe batches.
              </p>
            </div>

            <button
              type="button"
              onClick={handleBroadcast}
              disabled={isBroadcasting}
              className="w-full py-3 bg-gradient-to-r from-amber-500 via-orange-500 to-amber-600 text-slate-950 font-black rounded-xl text-xs uppercase tracking-wider shadow-lg shadow-amber-500/20 hover:opacity-95 transition flex items-center justify-center gap-2 disabled:opacity-50 cursor-pointer"
            >
              {isBroadcasting ? <RefreshCw size={15} className="animate-spin" /> : <Zap size={15} />}
              <span>{isBroadcasting ? "Executing Campaign Broadcast..." : `Launch Broadcast Now (${currentTargetCount})`}</span>
            </button>
          </div>
        </div>

        {/* Live Broadcast Report */}
        {broadcastResult && (
          <div className="p-4 rounded-2xl bg-emerald-500/10 border border-emerald-500/30 text-xs space-y-2 animate-fade-in">
            <div className="flex items-center justify-between font-bold text-emerald-400">
              <span className="flex items-center gap-1.5">
                <CheckCircle2 size={16} /> Broadcast Successfully Finished!
              </span>
              <span className="font-mono text-sm">
                Total Delivered: {broadcastResult.totalDelivered}
              </span>
            </div>
            <p className="text-muted leading-relaxed">
              {broadcastResult.message}
            </p>
            <div className="flex items-center gap-4 text-[11px] text-secondary font-mono pt-1">
              {broadcastResult.stats?.email && (
                <span>Email Sent: {broadcastResult.stats.email.sent}/{broadcastResult.stats.email.target}</span>
              )}
              {broadcastResult.stats?.whatsapp && (
                <span>WhatsApp Sent: {broadcastResult.stats.whatsapp.sent}/{broadcastResult.stats.whatsapp.target}</span>
              )}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

