"use client";

import React, { useEffect, useState, useCallback } from "react";
import { 
  TrendingUp, RefreshCw, Zap, ShieldCheck, 
  ArrowRight, CreditCard, Sparkles, AlertTriangle, CheckCircle2 
} from "lucide-react";
import { fetchWithAuth } from "@/lib/fetchWithAuth";

interface WaitlistFunnelCardProps {
  api: string;
  getAuthHeaders: () => Record<string, string>;
  triggerToast?: (msg: string, type: "success" | "error" | "info") => void;
}

interface FunnelData {
  rescue_cta_shown: number;
  rescue_cta_clicked: number;
  split_cta_shown: number;
  split_cta_clicked: number;
  rescue_free_used?: number;
  split_free_used?: number;
  free_credit_consumed: number;
  paywall_shown: number;
  blitz_cta_clicked: number;
  plan_purchase_from_funnel: number;
  since: string;
}

export function WaitlistFunnelCard({ api, getAuthHeaders, triggerToast }: WaitlistFunnelCardProps) {
  const [data, setData] = useState<FunnelData | null>(null);
  const [loading, setLoading] = useState<boolean>(true);

  const fetchFunnelData = useCallback(async () => {
    try {
      setLoading(true);
      const res = await fetchWithAuth(`${api}/api/admin/funnel-analytics`, {
        headers: getAuthHeaders(),
      });
      if (res.ok) {
        const json = await res.json();
        if (json.success && json.data) {
          setData(json.data);
        }
      }
    } catch (err) {
      if (triggerToast) {
        triggerToast("Failed to fetch funnel analytics", "error");
      }
    } finally {
      setLoading(false);
    }
  }, [api, getAuthHeaders, triggerToast]);

  useEffect(() => {
    fetchFunnelData();
  }, [fetchFunnelData]);

  const shown = (data?.rescue_cta_shown || 0) + (data?.split_cta_shown || 0);
  const clicks = (data?.rescue_cta_clicked || 0) + (data?.split_cta_clicked || 0);
  const ctr = shown > 0 ? Math.round((clicks / shown) * 100) : 0;
  const paywalls = data?.paywall_shown || 0;
  const purchases = data?.plan_purchase_from_funnel || 0;
  const paywallConv = paywalls > 0 ? Math.round((purchases / paywalls) * 100) : 0;

  return (
    <div className="p-6 rounded-3xl bg-card border border-subtle shadow-sm space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 border-b border-subtle pb-4">
        <div>
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 rounded-xl bg-amber-500/10 border border-amber-500/20 flex items-center justify-center text-amber-500">
              <TrendingUp size={18} />
            </div>
            <h3 className="text-base font-black text-main">Waitlist Next-Action Funnel (Today)</h3>
          </div>
          <p className="text-xs text-muted mt-1">
            Tracks user progression from Waitlist/RAC &rarr; Same-Train Rescue (1st free) &rarr; Split Journey &rarr; ₹9 Blitz Paywall.
          </p>
        </div>
        <button
          type="button"
          onClick={fetchFunnelData}
          disabled={loading}
          className="px-3 py-1.5 rounded-xl bg-surface hover:bg-input border border-subtle text-secondary hover:text-main text-xs font-bold transition flex items-center gap-2 shadow-xs cursor-pointer w-fit"
        >
          <RefreshCw size={13} className={loading ? "animate-spin text-primary" : ""} />
          <span>Refresh</span>
        </button>
      </div>

      {/* Primary Funnel Steps Grid */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
        <div className="p-4 rounded-2xl bg-surface border border-subtle space-y-1">
          <span className="text-[10px] font-bold uppercase tracking-wider text-muted">1. Advisor Shown</span>
          <div className="text-2xl font-black font-mono text-main">{shown}</div>
          <span className="text-[10px] text-muted block truncate">
            Rescue: {data?.rescue_cta_shown || 0} | Split: {data?.split_cta_shown || 0}
          </span>
        </div>

        <div className="p-4 rounded-2xl bg-surface border border-subtle space-y-1">
          <span className="text-[10px] font-bold uppercase tracking-wider text-muted">2. Action Clicks</span>
          <div className="text-2xl font-black font-mono text-main">{clicks}</div>
          <span className="text-[10px] text-emerald-400 font-bold block truncate">
            {ctr}% Click-through rate
          </span>
        </div>

        <div className="p-4 rounded-2xl bg-surface border border-subtle space-y-1">
          <span className="text-[10px] font-bold uppercase tracking-wider text-muted">3. Free Unlocks</span>
          <div className="text-2xl font-black font-mono text-emerald-400">{data?.free_credit_consumed || 0}</div>
          <span className="text-[10px] text-muted block truncate">
            Rescue: {data?.rescue_free_used || 0} | Split: {data?.split_free_used || 0}
          </span>
        </div>

        <div className="p-4 rounded-2xl bg-surface border border-subtle space-y-1">
          <span className="text-[10px] font-bold uppercase tracking-wider text-muted">4. Paywall Hits</span>
          <div className="text-2xl font-black font-mono text-amber-400">{paywalls}</div>
          <span className="text-[10px] text-muted block truncate">
            Exceeded free check
          </span>
        </div>
      </div>

      {/* Monetization / Conversion Row */}
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 pt-1">
        <div className="p-4 rounded-2xl bg-primary/5 border border-primary/20 flex items-center justify-between">
          <div className="space-y-1">
            <span className="text-[10px] font-black uppercase tracking-widest text-primary flex items-center gap-1.5">
              <Zap size={13} />
              ₹9 Blitz Pass Clicks
            </span>
            <div className="text-xl font-black font-mono text-main">
              {data?.blitz_cta_clicked || 0}
            </div>
            <p className="text-[10px] text-muted">Primary 30-min pass CTA conversions</p>
          </div>
          <div className="w-10 h-10 rounded-2xl bg-primary/10 border border-primary/20 flex items-center justify-center text-primary">
            <Zap size={20} />
          </div>
        </div>

        <div className="p-4 rounded-2xl bg-emerald-500/5 border border-emerald-500/20 flex items-center justify-between">
          <div className="space-y-1">
            <span className="text-[10px] font-black uppercase tracking-widest text-emerald-400 flex items-center gap-1.5">
              <CheckCircle2 size={13} />
              Paid Conversions
            </span>
            <div className="text-xl font-black font-mono text-emerald-400">
              {purchases}
            </div>
            <p className="text-[10px] text-muted">
              {paywallConv}% conversion from funnel paywalls
            </p>
          </div>
          <div className="w-10 h-10 rounded-2xl bg-emerald-500/10 border border-emerald-500/20 flex items-center justify-center text-emerald-400">
            <CreditCard size={20} />
          </div>
        </div>
      </div>
    </div>
  );
}
