"use client";

import React, { useEffect, useState, useCallback } from "react";
import { 
  Sparkles, Zap, Search, Activity, Flame, 
  RefreshCw, TrendingUp, ShieldCheck, ChevronRight, UserCheck
} from "lucide-react";
import { fetchWithAuth } from "@/lib/fetchWithAuth";

interface LivePulseData {
  today_paid_count: number;
  today_revenue: number;
  latest_purchases: Array<{
    id: string;
    user_id: string;
    user_display: string;
    plan_id: string;
    amount: number;
    provider?: string;
    created_at: string;
  }>;
  searches_today: number;
  pnr_checks_today: number;
  top_route_today: {
    source: string;
    destination: string;
    count: number;
  };
  timestamp: string;
}

interface AdminLivePulseTickerProps {
  api: string;
  getAuthHeaders: () => Record<string, string>;
  onNavigateToRevenue?: () => void;
}

const PLAN_LABELS: Record<string, { name: string; color: string }> = {
  safar_pro_30m: { name: "Blitz 30m", color: "text-amber-400" },
  safar_pro_1d: { name: "1-Day Pass", color: "text-purple-400" },
  safar_pro_7d: { name: "AI Pass 7D", color: "text-indigo-400" },
  safar_pro_30d: { name: "Pro Monthly", color: "text-emerald-400" },
  safar_pro_90d: { name: "Pro Yearly", color: "text-emerald-300" },
  safar_pro: { name: "Safar Pro", color: "text-blue-400" },
  beta: { name: "Beta Pass", color: "text-teal-400" },
};

export function AdminLivePulseTicker({ api, getAuthHeaders, onNavigateToRevenue }: AdminLivePulseTickerProps) {
  const [pulse, setPulse] = useState<LivePulseData | null>(null);
  const [loading, setLoading] = useState<boolean>(true);
  const [lastRefreshed, setLastRefreshed] = useState<Date>(new Date());
  const [activeBuyerIndex, setActiveBuyerIndex] = useState<number>(0);

  const fetchPulse = useCallback(async () => {
    try {
      setLoading(true);
      const res = await fetchWithAuth(`${api}/api/admin/live-pulse`, {
        headers: getAuthHeaders() as any
      });
      if (res.ok) {
        const json = await res.json();
        if (json.success && json.data) {
          setPulse(json.data);
          setLastRefreshed(new Date());
        }
      }
    } catch (err) {
      console.error("[LIVE_PULSE_FETCH_ERROR]", err);
    } finally {
      setLoading(false);
    }
  }, [api, getAuthHeaders]);

  // Initial load + periodic 30s auto-refresh
  useEffect(() => {
    fetchPulse();
    const interval = setInterval(() => {
      fetchPulse();
    }, 30000);
    return () => clearInterval(interval);
  }, [fetchPulse]);

  // Rotate through recent buyers if multiple exist
  useEffect(() => {
    if (!pulse?.latest_purchases || pulse.latest_purchases.length <= 1) return;
    const rotateTimer = setInterval(() => {
      setActiveBuyerIndex((prev) => (prev + 1) % pulse.latest_purchases.length);
    }, 4000);
    return () => clearInterval(rotateTimer);
  }, [pulse?.latest_purchases]);

  const currentBuyer = pulse?.latest_purchases?.[activeBuyerIndex];
  const buyerPlanInfo = currentBuyer ? (PLAN_LABELS[currentBuyer.plan_id] || { name: currentBuyer.plan_id || "Pro", color: "text-emerald-400" }) : null;

  return (
    <div className="w-full bg-gradient-to-r from-card via-card/95 to-card/90 border border-subtle/80 rounded-2xl p-3.5 md:p-4 mb-6 shadow-sm backdrop-blur-md relative overflow-hidden transition-all duration-300">
      {/* Subtle ambient light gradient in background */}
      <div className="absolute -top-12 -right-12 w-48 h-48 bg-emerald-500/10 rounded-full blur-3xl pointer-events-none" />
      <div className="absolute -bottom-12 -left-12 w-48 h-48 bg-indigo-500/10 rounded-full blur-3xl pointer-events-none" />

      {/* Top Header Strip: Live Status & Refresh */}
      <div className="flex items-center justify-between pb-3 border-b border-subtle/50 mb-3 text-xs">
        <div className="flex items-center gap-2.5">
          <span className="relative flex h-2.5 w-2.5">
            <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-emerald-400 opacity-75" />
            <span className="relative inline-flex rounded-full h-2.5 w-2.5 bg-emerald-500" />
          </span>
          <span className="font-mono uppercase font-black text-[11px] tracking-wider text-main flex items-center gap-1.5">
            Platform Live Pulse
            <span className="text-[10px] font-normal text-muted px-2 py-0.5 rounded-md bg-surface border border-subtle">
              Today: {new Date().toLocaleDateString('en-IN', { month: 'short', day: 'numeric' })}
            </span>
          </span>
        </div>

        <div className="flex items-center gap-2 text-muted">
          <span className="text-[10px] hidden sm:inline font-mono">
            Synced: {lastRefreshed.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' })}
          </span>
          <button
            onClick={fetchPulse}
            disabled={loading}
            title="Refresh Live Pulse"
            className="p-1.5 rounded-lg bg-surface hover:bg-input border border-subtle text-secondary hover:text-main transition flex items-center gap-1 text-[11px] font-semibold"
          >
            <RefreshCw size={12} className={loading ? "animate-spin text-primary" : ""} />
            <span className="hidden sm:inline">Refresh</span>
          </button>
        </div>
      </div>

      {/* 4-Column Bento Pulse Grid */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-3">
        {/* Card 1: Paid Plans & Revenue Today */}
        <div 
          onClick={onNavigateToRevenue}
          className={`p-3 rounded-xl border transition-all duration-200 cursor-pointer ${
            pulse?.today_paid_count && pulse.today_paid_count > 0 
              ? "bg-gradient-to-br from-emerald-500/10 via-emerald-500/5 to-transparent border-emerald-500/30 hover:border-emerald-500/60 shadow-sm" 
              : "bg-surface border-subtle hover:border-strong"
          }`}
        >
          <div className="flex items-center justify-between text-xs text-muted mb-1">
            <span className="flex items-center gap-1.5 font-bold uppercase tracking-wider text-[10px] text-emerald-500">
              <Zap size={13} className="text-emerald-500" /> Paid Plans Today
            </span>
            <span className="font-mono text-emerald-500 text-[11px] font-black">
              ₹{pulse?.today_revenue ?? 0}
            </span>
          </div>
          
          <div className="flex items-baseline gap-2 mt-1">
            <div className="text-2xl font-black text-main font-mono">
              {pulse?.today_paid_count ?? 0}
            </div>
            <div className="text-[11px] font-semibold text-emerald-600 dark:text-emerald-400">
              {pulse?.today_paid_count === 1 ? "Subscriber" : "Subscribers"}
            </div>
          </div>

          {/* Dynamic Recent Buyer Ticker */}
          <div className="mt-2 pt-1.5 border-t border-subtle/40 text-[10px] text-muted flex items-center justify-between min-h-[22px]">
            {currentBuyer ? (
              <div className="flex items-center gap-1.5 truncate">
                <span className="w-1.5 h-1.5 rounded-full bg-emerald-400 animate-pulse shrink-0" />
                <span className="font-semibold text-main truncate">{currentBuyer.user_display}</span>
                <span className="text-muted">bought</span>
                <span className={`font-bold ${buyerPlanInfo?.color || "text-emerald-400"}`}>
                  {buyerPlanInfo?.name}
                </span>
                <span className="text-muted font-mono font-semibold">(₹{currentBuyer.amount})</span>
              </div>
            ) : (
              <span className="text-muted italic">Awaiting first conversion today</span>
            )}
            <ChevronRight size={12} className="text-muted shrink-0 ml-1" />
          </div>
        </div>

        {/* Card 2: Searches Today */}
        <div className="p-3 rounded-xl bg-surface border border-subtle hover:border-indigo-500/40 transition">
          <div className="flex items-center justify-between text-xs text-muted mb-1">
            <span className="flex items-center gap-1.5 font-bold uppercase tracking-wider text-[10px] text-indigo-400">
              <Search size={13} className="text-indigo-400" /> Searches Today
            </span>
            <span className="text-[9px] text-muted font-mono uppercase bg-card px-1.5 py-0.5 rounded border border-subtle">
              Engine Live
            </span>
          </div>

          <div className="flex items-baseline gap-2 mt-1">
            <div className="text-2xl font-black text-main font-mono">
              {(pulse?.searches_today ?? 0).toLocaleString()}
            </div>
            <div className="text-[11px] text-muted">Journey Queries</div>
          </div>

          <div className="mt-2 pt-1.5 border-t border-subtle/40 text-[10px] text-secondary flex items-center gap-1">
            <TrendingUp size={11} className="text-indigo-400" />
            <span>Trains, split routes &amp; hubs</span>
          </div>
        </div>

        {/* Card 3: PNR Status Lookups */}
        <div className="p-3 rounded-xl bg-surface border border-subtle hover:border-sky-500/40 transition">
          <div className="flex items-center justify-between text-xs text-muted mb-1">
            <span className="flex items-center gap-1.5 font-bold uppercase tracking-wider text-[10px] text-sky-400">
              <Activity size={13} className="text-sky-400" /> PNR Checks Today
            </span>
            <span className="text-[9px] text-muted font-mono uppercase bg-card px-1.5 py-0.5 rounded border border-subtle">
              Telemetry
            </span>
          </div>

          <div className="flex items-baseline gap-2 mt-1">
            <div className="text-2xl font-black text-main font-mono">
              {(pulse?.pnr_checks_today ?? 0).toLocaleString()}
            </div>
            <div className="text-[11px] text-muted">Passenger Lookups</div>
          </div>

          <div className="mt-2 pt-1.5 border-t border-subtle/40 text-[10px] text-secondary flex items-center gap-1">
            <ShieldCheck size={11} className="text-sky-400" />
            <span>AI probability &amp; confirmation tracking</span>
          </div>
        </div>

        {/* Card 4: #1 Trending Route */}
        <div className="p-3 rounded-xl bg-surface border border-subtle hover:border-amber-500/40 transition">
          <div className="flex items-center justify-between text-xs text-muted mb-1">
            <span className="flex items-center gap-1.5 font-bold uppercase tracking-wider text-[10px] text-amber-400">
              <Flame size={13} className="text-amber-500" /> Hot Route Today
            </span>
            {pulse?.top_route_today?.count ? (
              <span className="text-[10px] font-mono text-amber-500 font-bold bg-amber-500/10 px-1.5 py-0.5 rounded border border-amber-500/20">
                {pulse.top_route_today.count} searches
              </span>
            ) : null}
          </div>

          <div className="flex items-baseline gap-2 mt-1 truncate">
            <div className="text-lg font-black text-main truncate font-mono">
              {pulse?.top_route_today?.source || "NDLS"} <span className="text-amber-500 font-bold">&rarr;</span> {pulse?.top_route_today?.destination || "BSB"}
            </div>
          </div>

          <div className="mt-2 pt-1.5 border-t border-subtle/40 text-[10px] text-secondary flex items-center gap-1 truncate">
            <Sparkles size={11} className="text-amber-400 shrink-0" />
            <span className="truncate">Highest passenger booking intent</span>
          </div>
        </div>
      </div>
    </div>
  );
}
